
var LOGO_B64 = "";
'use strict';
/* =====================================================================
   OK DESPACHO — app offline. Módulos: Config, DB, Normalizer, ExcelImporter,
   OrderIndex, FinancialIndex, ShippingMatcher, CalculationEngine, RouteStore,
   UI, ExcelExporter.  Ningún dato sale del equipo.
   ===================================================================== */

/* ---------------- utilidades ---------------- */
const $ = (s, el) => (el || document).querySelector(s);
const $$ = (s, el) => Array.from((el || document).querySelectorAll(s));
const r2 = v => Math.round((Number(v) + Number.EPSILON) * 100) / 100;
const fmtARS = new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtNum = new Intl.NumberFormat('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const ars = v => (v == null || v === '' || isNaN(v)) ? '' : fmtARS.format(v).replace(/\u00a0/g, ' ');
const num = v => (v == null || v === '' || isNaN(v)) ? '' : fmtNum.format(v);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const pad = n => (n < 10 ? '0' : '') + n;
function todayISO() { const d = new Date(); return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function isoToDMY(iso) { if (!iso) return ''; const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : iso; }
function dmyToISO(s) {
  const m = String(s || '').trim().match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2}|\d{4})$/);
  if (!m) return '';
  let y = +m[3]; if (y < 100) y += 2000;
  const d = +m[1], mo = +m[2];
  const dt = new Date(y, mo - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== mo - 1 || dt.getDate() !== d) return '';
  return y + '-' + pad(mo) + '-' + pad(d);
}
function uid() { return 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }
// Identificador de hoja: UUID seguro (lo usa el servidor para el dueño del borrador)
function sheetUid() { return (window.crypto && crypto.randomUUID) ? crypto.randomUUID() : uid() + uid(); }
function parseMoney(s) {
  if (s == null) return null;
  if (typeof s === 'number') return isFinite(s) ? s : null;
  let t = String(s).replace(/\$/g, '').replace(/\s/g, '').trim();
  if (!t) return null;
  if (t.indexOf(',') >= 0) t = t.replace(/\./g, '').replace(',', '.');
  else if ((t.match(/\./g) || []).length > 1) t = t.replace(/\./g, '');
  else if (/^-?\d{1,3}\.\d{3}$/.test(t)) t = t.replace('.', '');
  const n = parseFloat(t);
  return isFinite(n) ? r2(n) : null;
}
function debounce(fn, ms) { let t; return function () { clearTimeout(t); const a = arguments; t = setTimeout(() => fn.apply(null, a), ms); }; }
function toast(msg, ms) {
  const t = $('#toast'); t.textContent = msg; t.classList.add('show');
  clearTimeout(toast._t); toast._t = setTimeout(() => t.classList.remove('show'), ms || 3200);
}

/* ---------------- Config ---------------- */
const Config = {
  defaults() {
    return {
      pay: { FAC: 'ICBC', NDP: 'SIMPLY' },
      shipCosts: { ESTE: [13000], ALREDEDORES: [2000, 4000, 10000] },
      creditMonths: 6,
      creditTypes: ['NOC', 'REC', 'REP'], // únicos tipos que pueden ser saldo a favor
      tolerance: 1,
      opNotesInExcel: false,
      exportCols: [true, true, true, true, true, true, true, true, true, true],
      carriers: ['UCO', 'VASCA', 'ANDESMAR', 'CRISTIAN TORRES - ESTE', 'CRISTIAN TORRES - ALREDEDORES', 'MARCHETTI', 'TRANSPORTE INTERNO'],
      rules: [
        { estado: 'CRISTIAN', zona: 'ESTE', carrier: 'CRISTIAN TORRES - ESTE' },
        { estado: 'CRISTIAN', zona: '', carrier: 'CRISTIAN TORRES - ALREDEDORES' },
        { estado: 'ALREDEDORES', zona: '', carrier: 'CRISTIAN TORRES - ALREDEDORES' },
        { estado: 'GRAN MENDOZA', zona: '', carrier: 'CRISTIAN TORRES - ALREDEDORES' },
        { estado: 'ZONA ESTE', zona: '', carrier: 'CRISTIAN TORRES - ESTE' },
        { estado: 'UCO', zona: '', carrier: 'UCO' },
        { estado: 'VASCA', zona: '', carrier: 'VASCA' },
        { estado: 'ANDESMAR', zona: '', carrier: 'ANDESMAR' },
        { estado: 'MARCHETTI', zona: '', carrier: 'MARCHETTI' }
      ]
    };
  },
  value: null,
  load(v) {
    const d = this.defaults();
    this.value = Object.assign(d, v || {});
    this.value.pay = Object.assign(d.pay, (v && v.pay) || {});
    this.value.shipCosts = Object.assign(this.defaults().shipCosts, (v && v.shipCosts) || {});
    if (v && v.nocMonths != null && v.creditMonths == null) this.value.creditMonths = v.nocMonths;
    delete this.value.nocMonths;
    if (!Array.isArray(this.value.exportCols) || this.value.exportCols.length !== 10) this.value.exportCols = d.exportCols.slice();
    if (!this.value.carriers.includes('TRANSPORTE INTERNO')) this.value.carriers.push('TRANSPORTE INTERNO'); // siempre visible en Despacho
    // Agrega una sola vez la regla "ZONA ESTE" a configuraciones guardadas anteriores
    if (!this.value.rulesV || this.value.rulesV < 2) {
      if (!this.value.rules.some(r => Normalizer.name(r.estado) === 'ZONA ESTE')) {
        const i = this.value.rules.findIndex(r => Normalizer.name(r.estado) === 'UCO');
        this.value.rules.splice(i >= 0 ? i : this.value.rules.length, 0, { estado: 'ZONA ESTE', zona: '', carrier: 'CRISTIAN TORRES - ESTE' });
      }
      this.value.rulesV = 2;
    }
  },
  // Modo online: las reglas financieras vigentes del servidor son la ÚNICA fuente (FAC/NDP, costos de envío, antigüedad, tipos de crédito, tolerancia).
  // Se re-imponen en cada lectura: un cambio local no puede alterar el cálculo.
  get() {
    const s = window.OKD_SERVER_RULES, v = this.value, rr = window.OKD_SERVER_ROUTING;
    if (rr && v) v.rules = JSON.parse(JSON.stringify(rr)); // reglas Estado/Zona → Transportista del servidor (única fuente online)
    if (s && v) { v.pay = Object.assign({}, v.pay, s.pay || {}); if (s.shipCosts) v.shipCosts = JSON.parse(JSON.stringify(s.shipCosts));
      ['creditMonths', 'tolerance', 'creditTypes'].forEach(k => { if (s[k] != null) v[k] = JSON.parse(JSON.stringify(s[k])); }); }
    return v;
  },
  isCristian(c) { return /CRISTIAN/i.test(c || ''); },
  payFor(doc) {
    const t = Normalizer.compType(doc);
    if (t === 'FAC') return this.value.pay.FAC;
    if (t === 'NDP') return this.value.pay.NDP;
    return 'REVISAR';
  },
  carrierFor(estado, zona) {
    const e = ' ' + Normalizer.name(estado) + ' ', z = ' ' + Normalizer.name(zona) + ' ';
    for (const r of this.get().rules) {
      const re = Normalizer.name(r.estado), rz = Normalizer.name(r.zona);
      if (!re || !r.carrier) continue;
      if (e.indexOf(' ' + re + ' ') < 0) continue;
      if (rz && z.indexOf(' ' + rz + ' ') < 0) continue;
      return r.carrier;
    }
    return '';
  }
};

/* ---------------- DB (IndexedDB) ---------------- */
const DB = {
  db: null,
  open() {
    return new Promise((res) => {
      let req;
      try { req = indexedDB.open('ok_despacho', 1); } catch (e) { res(null); return; }
      req.onupgradeneeded = () => req.result.createObjectStore('kv');
      req.onsuccess = () => { this.db = req.result; res(this.db); };
      req.onerror = () => res(null);
    });
  },
  tx(mode, fn) {
    return new Promise((res) => {
      if (!this.db) { res(null); return; }
      const t = this.db.transaction('kv', mode), st = t.objectStore('kv');
      const r = fn(st);
      t.oncomplete = () => res(r && 'result' in r ? r.result : null);
      t.onerror = () => res(null);
    });
  },
  get(k) { return this.tx('readonly', st => st.get(k)); },
  set(k, v) { return this.tx('readwrite', st => st.put(v, k)); },
  clear() { return this.tx('readwrite', st => st.clear()); }
};

/* ---------------- Normalizer ---------------- */
const Normalizer = {
  comp(s) { return String(s || '').toUpperCase().replace(/[\s\[\]\-_.()]/g, ''); },
  // Versión SOLO visual: "FAC [A] 0020-00001965" -> "FAC [A] 20-1965" (el original se conserva para cruces)
  shortComp(s) {
    const t = String(s || '').trim();
    const m = t.match(/^(.*?)(\d+)-(\d+)\s*$/);
    if (!m) return t;
    const z = x => x.replace(/^0+(?=\d)/, '');
    return (m[1].replace(/\s+$/, '') + ' ' + z(m[2]) + '-' + z(m[3])).trim();
  },
  compType(s) { const m = String(s || '').trim().match(/^([A-Za-z]{3})/); return m ? m[1].toUpperCase() : ''; },
  name(s) {
    return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase()
      .replace(/[^A-Z0-9]+/g, ' ').trim();
  },
  splitClient(s) {
    const m = String(s || '').match(/^(.*?)\s*\[(.*)\]\s*$/);
    return m ? { name: m[1].trim(), fantasy: m[2].trim() } : { name: String(s || '').trim(), fantasy: '' };
  },
  obsParts(obs) { return String(obs || '').split(/\\n|\n|\r|\|/).map(x => x.trim()).filter(Boolean); },
  address(obs) {
    for (const p of this.obsParts(obs)) {
      const m = p.match(/^direcci[oó]n\s*:\s*(.+)$/i);
      if (m && m[1].trim().length > 2) return m[1].trim();
    }
    return '';
  },
  refs(obs) {
    const clean = String(obs || '').replace(/pedido\s*web\s*:\s*\d+/ig, ' ');
    const out = [];
    (clean.match(/(?<!\d)\d{4,6}(?!\d)/g) || []).forEach(x => { const v = String(parseInt(x, 10)); if (out.indexOf(v) < 0) out.push(v); });
    return out;
  },
  daysBetween(a, b) {
    if (!a || !b) return 9999;
    return Math.abs((Date.parse(a + 'T00:00:00') - Date.parse(b + 'T00:00:00')) / 86400000);
  }
};

/* ---------------- ExcelImporter (Web Worker con SheetJS embebido) ---------------- */
const ExcelImporter = {
  worker: null, jobs: new Map(), seq: 0, fallbackReady: false,
  init() {
    try {
      const src = $('#src-xlsx').textContent + '\n;\n' + $('#src-worker').textContent;
      const url = URL.createObjectURL(new Blob([src], { type: 'text/javascript' }));
      this.worker = new Worker(url);
      this.worker.onmessage = e => {
        const j = this.jobs.get(e.data.id); if (!j) return;
        if (e.data.type === 'progress') j.progress(e.data.p, e.data.msg);
        else { this.jobs.delete(e.data.id); j.resolve(e.data.result); }
      };
      this.worker.onerror = () => { this.worker = null; };
    } catch (e) { this.worker = null; }
  },
  ensureFallback() {
    if (this.fallbackReady) return;
    const s1 = document.createElement('script'); s1.textContent = $('#src-xlsx').textContent; document.head.appendChild(s1);
    const s2 = document.createElement('script'); s2.textContent = $('#src-worker').textContent; document.head.appendChild(s2);
    this.fallbackReady = true;
  },
  parse(file, progress) {
    return file.arrayBuffer().then(buf => new Promise(resolve => {
      if (this.worker) {
        const id = ++this.seq;
        this.jobs.set(id, { resolve, progress });
        this.worker.postMessage({ id, buffer: buf, fileName: file.name }, [buf]);
      } else {
        this.ensureFallback();
        setTimeout(() => {
          try { resolve(window.ExcelImporterCore.parse(buf, file.name, progress)); }
          catch (err) { resolve({ ok: false, fileName: file.name, error: 'No se pudo leer el archivo: ' + err.message }); }
        }, 30);
      }
    }));
  }
};

/* ---------------- OrderIndex ---------------- */
const OrderIndex = {
  byId: new Map(), mainToShips: new Map(), byClient: new Map(), addrByClient: new Map(),
  build(records) {
    this.byId = new Map(); this.mainToShips = new Map(); this.byClient = new Map(); this.addrByClient = new Map();
    (records || []).forEach(o => this.byId.set(o.id, o));
    const sorted = (records || []).slice().sort((a, b) => (+b.id) - (+a.id));
    for (const o of sorted) {
      o.clientN = Normalizer.name(o.cliente);
      o.kind = o.isShipping ? 'ENVIO' : (o.shipLines > 0 ? 'MERCADERIA CON ENVIO' : 'MERCADERIA');
      if (!this.byClient.has(o.clientN)) this.byClient.set(o.clientN, []);
      this.byClient.get(o.clientN).push(o.id);
      const ad = o.domicilio || Normalizer.address(o.obs) || Normalizer.address(o.obsPedido);
      if (ad && !this.addrByClient.has(o.clientN)) this.addrByClient.set(o.clientN, { addr: ad, id: o.id });
    }
    for (const o of records || []) {
      if (!o.isShipping) continue;
      o.refs = Normalizer.refs((o.obs || '') + ' ' + (o.obsPedido || '')).filter(r => r !== o.id);
      o.validRefs = o.refs.filter(r => this.byId.has(r) && !this.byId.get(r).isShipping);
      o.validRefs.forEach(r => {
        if (!this.mainToShips.has(r)) this.mainToShips.set(r, []);
        this.mainToShips.get(r).push(o.id);
      });
    }
  },
  get(id) { return this.byId.get(String(id)); },
  size() { return this.byId.size; }
};

/* ---------------- FinancialIndex ---------------- */
const FinancialIndex = {
  comps: new Map(), byClient: new Map(), saByClient: new Map(), ccByCuit: new Map(), ccByName: new Map(), ccByFull: new Map(),
  scVersion: 0,
  buildSC(records, v, importId) {
    this.comps = new Map(); this.byClient = new Map(); this.saByClient = new Map(); this.scVersion = v || 0; this.importId = importId || '';
    const docs = [];
    for (const r of records || []) {
      r.key = r.cuit || Normalizer.name(r.c);
      if (r.san) { if (r.v != null && Math.abs(r.v) > 0.004) this.saByClient.set(r.key, r2((this.saByClient.get(r.key) || 0) + r.v)); continue; }
      r.n = Normalizer.comp(r.comp); r.t = Normalizer.compType(r.comp);
      docs.push(r);
    }
    // Financiación propia: agrupa partes/cuotas del mismo comprobante y descarta duplicados exactos
    const g = window.OKFinancing.groupAll(docs, this.importId);
    this.comps = g.groups;
    this.finSync = FinancingPlans.sync(g.groups, this.importId); // se espera antes de mostrar financiación, ofrecer NOC a financiación o publicar
    for (const r of g.uniqueRows) {
      if (!this.byClient.has(r.key)) this.byClient.set(r.key, []);
      this.byClient.get(r.key).push(r);
    }
    this.nocSync = NocReconcile.run(this.importId);                // RC3: conciliación NOC con la importación ya indexada
  },
  buildCC(records) {
    this.ccByCuit = new Map(); this.ccByName = new Map(); this.ccByFull = new Map();
    for (const r of records || []) {
      if (r.cuit) this.ccByCuit.set(r.cuit, r);
      const n = Normalizer.name(r.c);
      if (!this.ccByName.has(n)) this.ccByName.set(n, []);
      this.ccByName.get(n).push(r);
      if (r.f) this.ccByFull.set(n + '|' + Normalizer.name(r.f), r);
    }
  },
  findComp(doc, clientName) {
    if (!doc) return null;
    const list = this.comps.get(Normalizer.comp(doc));
    if (!list || !list.length) return null;
    if (list.length === 1) return list[0];
    const sc = Normalizer.splitClient(clientName), n = Normalizer.name(sc.name);
    return list.find(r => Normalizer.name(r.c) === n) || list[0];
  },
  findCC(cuit, clientName) {
    if (cuit && this.ccByCuit.has(cuit)) return this.ccByCuit.get(cuit);
    const sc = Normalizer.splitClient(clientName);
    const n = Normalizer.name(sc.name), f = Normalizer.name(sc.fantasy);
    if (f && this.ccByFull.has(n + '|' + f)) return this.ccByFull.get(n + '|' + f);
    const list = this.ccByName.get(n) || this.ccByName.get(Normalizer.name(clientName));
    if (list && list.length === 1) return list[0];
    return null; // ambiguo o inexistente: no se adivina
  },
  clientRows(key) { return this.byClient.get(key) || []; }
};

/* ---------------- ShippingMatcher ---------------- */
const ShippingMatcher = {
  shipGroup(ship, carrier) {
    const code = (ship && ship.shipCode) || '';
    if (/ESTE/.test(code)) return 'ESTE';
    if (/ALREDEDORES|CENTRO/.test(code)) return 'ALREDEDORES';
    return /ESTE/i.test(carrier || '') ? 'ESTE' : 'ALREDEDORES';
  },
  // Pedidos de mercadería del mismo cliente a los que podría corresponder un envío sin referencia
  mainCandidates(ship) {
    return (OrderIndex.byClient.get(ship.clientN) || []).map(x => OrderIndex.get(x))
      .filter(x => !x.isShipping && !(x.shipLines > 0) && !OrderIndex.mainToShips.has(x.id) && Normalizer.daysBetween(x.fecha, ship.fecha) <= 3)
      .sort((a, b) => (+a.id) - (+b.id));
  },
  // Devuelve la entrega resuelta para un número ingresado
  resolve(id) {
    const o = OrderIndex.get(id);
    if (!o) return null;
    const res = { entered: o.id, main: null, ship: null, mainRef: '', flags: [], notes: [] };
    if (o.isShipping) {
      res.ship = o;
      if (o.validRefs && o.validRefs.length) {
        const m = OrderIndex.get(o.validRefs[0]);
        res.main = m;
        if (m.clientN !== o.clientN) {
          res.flags.push({ level: 'warn', code: 'RELACIÓN DE ENVÍO DUDOSA', text: 'El envío ' + o.id + ' menciona el pedido ' + m.id + ', pero el cliente es distinto (' + m.cliente + ').' });
        } else {
          res.notes.push({ level: 'ship', text: 'El pedido ' + o.id + ' es costo de envío: sus Observaciones ("' + Normalizer.obsParts(o.obs)[0] + '") relacionan el pedido principal ' + m.id + '.' });
        }
        if (o.validRefs.length > 1) res.flags.push({ level: 'warn', code: 'REVISAR', text: 'Las observaciones del envío mencionan varios pedidos: ' + o.validRefs.join(', ') + '. Se tomó ' + m.id + '.' });
      } else if (o.refs && o.refs.length) {
        res.mainRef = o.refs[0];
        res.flags.push({ level: 'warn', code: 'REVISAR', text: 'El envío ' + o.id + ' menciona el pedido ' + o.refs[0] + ', que no está en el informe de pedidos cargado.' });
      } else {
        const cands = this.mainCandidates(o);
        if (cands.length === 1) {
          res.main = cands[0];
          res.flags.push({ level: 'warn', code: 'RELACIÓN DE ENVÍO DUDOSA', text: 'El envío ' + o.id + ' no menciona ningún pedido en Observaciones. Se asoció ' + cands[0].id + ' solo por mismo cliente y fecha cercana.' });
        } else if (cands.length > 1) {
          // Ambiguo: no se elige el primero; queda POR ASOCIAR
          res.shipPending = true; res.candidates = cands.map(x => x.id);
        } else {
          res.flags.push({ level: 'warn', code: 'REVISAR', text: 'El envío ' + o.id + ' no tiene pedido principal relacionado en Observaciones.' });
        }
      }
    } else {
      res.main = o;
      const ships = OrderIndex.mainToShips.get(o.id) || [];
      if (ships.length) {
        const s = OrderIndex.get(ships[0]);
        res.ship = s;
        if (s.clientN !== o.clientN) res.flags.push({ level: 'warn', code: 'RELACIÓN DE ENVÍO DUDOSA', text: 'El envío ' + s.id + ' menciona este pedido pero pertenece a otro cliente (' + s.cliente + ').' });
        else res.notes.push({ level: 'ship', text: 'Se agregó el envío ' + s.id + ': sus Observaciones relacionan el pedido ' + o.id + '.' });
        if (ships.length > 1) res.flags.push({ level: 'warn', code: 'REVISAR', text: 'Hay varios pedidos de envío que mencionan ' + o.id + ': ' + ships.join(', ') + '. Se tomó ' + s.id + '.' });
      } else {
        const cands = o.shipLines > 0 ? [] : (OrderIndex.byClient.get(o.clientN) || []).map(x => OrderIndex.get(x))
          .filter(x => x.isShipping && !(x.validRefs && x.validRefs.length) && !(x.refs && x.refs.length) && Normalizer.daysBetween(x.fecha, o.fecha) <= 3);
        if (cands.length === 1) {
          const mains = this.mainCandidates(cands[0]);
          if (mains.length > 1) {
            // El envío podría corresponder a varias mercaderías: no se asocia automáticamente
            res.pendingShip = cands[0]; res.candidates = mains.map(x => x.id);
          } else {
            res.ship = cands[0];
            res.flags.push({ level: 'warn', code: 'RELACIÓN DE ENVÍO DUDOSA', text: 'Se asoció el envío ' + cands[0].id + ' solo por mismo cliente y fecha cercana (sus Observaciones no mencionan este pedido).' });
          }
        }
      }
    }
    return res;
  }
};

/* ---------------- ComprobanteMatcher: comprobantes alternativos en Saldo Comprobante ----------------
   Para pedidos sin factura en el informe o con factura no encontrada. Nunca asigna solo: el operador confirma.
   Nunca propone comprobantes de otro CUIT. */
const ComprobanteMatcher = {
  DEBIT: new Set(['FAC', 'NDP', 'NOD', 'NDB']),
  // Pedido al que ya está vinculado un comprobante (en la hoja o en el informe), o ''
  linkedTo(n, row) {
    const r = RouteStore.rows.find(x => x !== row && ((x.mainDoc && Normalizer.comp(x.mainDoc) === n) || (x.shipDoc && Normalizer.comp(x.shipDoc) === n)));
    if (r) return String(r.mainOrder || r.shipOrder);
    let found = '';
    OrderIndex.byId.forEach(o => { if (!found && o.id !== String(row.mainOrder) && o.id !== String(row.shipOrder) && (o.facturas || []).some(f => Normalizer.comp(f) === n)) found = o.id; });
    return found;
  },
  candidates(row) {
    const src = row.src || {}, fecha = src.fechaPedido || row.fecha;
    const cc = FinancialIndex.findCC('', row.cliente);
    const cuit = cc && cc.cuit ? cc.cuit : '';
    const nm = Normalizer.name(Normalizer.splitClient(row.cliente).name);
    let pool = cuit ? FinancialIndex.clientRows(cuit) : FinancialIndex.clientRows(nm);
    if (cuit) pool = pool.filter(r => r.cuit === cuit); // seguridad por CUIT
    const own = new Set([row.mainDoc, row.shipDoc].filter(Boolean).map(Normalizer.comp));
    const total = src.mainTotal;
    const out = pool.filter(r => this.DEBIT.has(r.t) && r.d && !own.has(r.n) && Normalizer.daysBetween(r.d, fecha) <= 10).map(r => {
      const dd = Normalizer.daysBetween(r.d, fecha);
      let score = cuit ? 3 : 2;
      if (dd <= 1) score += 2; else if (dd <= 3) score += 1;
      const compat = total != null && r.m != null && Math.abs(r.m - total) <= Math.max(1, total * 0.01);
      if (compat) score += 3;
      if (r.s == null || r.s > 0.004) score += 1;
      return { r, score, compat, level: score >= 7 ? 'ALTA' : score >= 5 ? 'MEDIA' : 'BAJA', linked: this.linkedTo(r.n, row), byCuit: !!cuit };
    });
    return out.sort((a, b) => b.score - a.score || Normalizer.daysBetween(a.r.d, fecha) - Normalizer.daysBetween(b.r.d, fecha)).slice(0, 6);
  },
  needs(row) {
    if (!row.auto || row.shipPending || row.compNone) return false;
    if (!row.mainDoc) return true;
    return !FinancialIndex.findComp(row.mainDoc, row.cliente) && !row.compLink;
  }
};

/* ---------------- CalculationEngine (v3) ----------------
   SALDO CUENTA CORRIENTE = TOPE REAL DE COBRO, salvo créditos antiguos concretos e identificados.
   Por cliente:  saldo ajustado = Saldo CC + créditos antiguos (con fecha, > límite, con saldo abierto).
   Por entrega:  monto = MAX(0, MIN(comprobantes, parte del saldo ajustado que le corresponde)).
   Si el cliente tiene varias entregas en la hoja, la reducción se asigna primero al comprobante
   más antiguo (independiente del orden de la tabla). Con envío, se preserva primero el envío.
   Los créditos vigentes ya están reflejados en la cuenta corriente: no se restan de nuevo.
*/
const CalculationEngine = {
  refISO() { return RouteStore.sheetDate || todayISO(); },
  limitISO() {
    const ref = this.refISO(), m = ref.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    const d = new Date(+m[1], +m[2] - 1, +m[3]);
    d.setMonth(d.getMonth() - (Number(Config.get().creditMonths) || 0));
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  },
  ageText(d) {
    if (!d) return 'sin fecha';
    const days = Math.round(Normalizer.daysBetween(d, this.refISO()));
    if (days < 60) return days + ' días';
    return (Math.round(days / 30.44 * 10) / 10).toString().replace('.', ',') + ' meses';
  },
  // Créditos del cliente clasificados por antigüedad
  credits(key) {
    const limit = this.limitISO();
    const rows = FinancialIndex.clientRows(key);
    const allowed = new Set((Config.get().creditTypes || ['NOC', 'REC', 'REP']).map(t => String(t).toUpperCase()));
    const list = rows.filter(r => r.s != null && r.s < -0.004 && allowed.has(r.t)).map(r => ({
      comp: r.comp, t: r.t || '', d: r.d || '', amt: r2(-r.s), orig: r.m != null ? r2(Math.abs(r.m)) : null, cuit: r.cuit || '', cat: !r.d ? 'undated' : (r.d < limit ? 'old' : 'valid')
    })).sort((a, b) => (a.d || '9999').localeCompare(b.d || '9999') || a.comp.localeCompare(b.comp));
    const sum = cat => r2(list.filter(x => x.cat === cat).reduce((s, x) => s + x.amt, 0));
    const visible = r2(rows.reduce((s, r) => s + (r.s || 0), 0));
    return { list, old: sum('old'), valid: sum('valid'), undated: sum('undated'), visible };
  },
  computeAll(rows) {
    const auto = rows.filter(r => r.auto);
    // 1) datos base de cada entrega
    auto.forEach(r => { r.calc = this.base(r); });
    // 2) agrupar por cliente con cuenta corriente y repartir el tope
    const groups = new Map();
    auto.forEach(r => { const c = r.calc; if (c.ready) { if (!groups.has(c.key)) groups.set(c.key, []); groups.get(c.key).push(r); } });
    groups.forEach(list => this.allocate(list));
    // 3) aplicar al monto
    for (const row of auto) {
      const c = row.calc;
      Money.apply(row);
      if (row.montoManual && row.manualBase !== undefined && !sameMoney(row.manualBase, c.suggested)) {
        c.flags.push({ level: 'warn', code: 'REVISAR', text: 'El monto sugerido por sistema cambió de ' + (row.manualBase == null ? 'PENDIENTE' : ars(row.manualBase)) + ' a ' + (c.suggested == null ? 'PENDIENTE' : ars(c.suggested)) + '. Se conservó el monto editado manualmente (' + (row.monto == null ? 'vacío' : ars(row.monto)) + ').' });
      }
    }
  },
  base(row) {
    const cfg = Config.get();
    const c = {
      flags: [], notes: [], mainDue: null, shipDue: null, target: null, cc: null, suggested: null, mainCollect: null, shipCollect: null,
      oldIdentified: 0, oldExcluded: 0, validReflected: 0, undated: 0, adjusted: null, gap: 0, applicable: null, movements: [],
      ref: this.refISO(), months: cfg.creditMonths, cuit: '', key: '', ready: false, sortDate: '', sortComp: '', groupSize: 1, sa: 0, recon: null
    };
    const flag = (level, code, text) => c.flags.push({ level, code, text });
    const note = (text, level) => c.notes.push({ level: level || 'info', text });
    let mainR = null, shipR = null, missing = false;
    const isCT = Config.isCristian(row.carrierOrig || row.transportista);
    // Saldo de un comprobante: distingue vacío (no informado), cero real y valor
    const dueOf = (r, label) => {
      if (r.fin) {
        const pt = window.OKFinancing.partsText(r.fin);
        if (r.fin.status === 'POSIBLE_FINANCIACION_REVISAR') { missing = true; flag('warn', 'POSIBLE FINANCIACIÓN PROPIA · REVISAR', label + ' ' + Normalizer.shortComp(r.comp) + ': ' + pt + ' (mismo vencimiento o sin cuota). No se suman: completá el monto a mano.'); return null; }
        if (r.fin.status !== 'NORMAL') flag('info', r.fin.label, label + ' ' + Normalizer.shortComp(r.comp) + ': ' + pt + ' · saldo agrupado ' + ars(r.fin.total) + '.');
        if (r.fin.duplicates) note(r.fin.duplicates + ' fila(s) duplicadas exactas de ' + Normalizer.shortComp(r.comp) + ' no se sumaron.');
        c.finGroup = r.fin;
      }
      if (r.s == null) {
        if (isCT) { missing = true; flag('error', 'SALDO NO INFORMADO — REVISAR', label + ' ' + r.comp + ': Saldo Comp. vacío. En Cristian Torres no se reemplaza por el importe de la factura: completá el monto a mano.'); return null; }
        if (r.m == null) { missing = true; flag('error', 'SALDO NO INFORMADO — REVISAR', label + ' ' + r.comp + ': Saldo Comp. vacío y sin importe original.'); return null; }
        flag('soft', 'SALDO NO INFORMADO', 'SALDO NO INFORMADO — SE TOMA IMPORTE DE FACTURA: ' + ars(r.m) + ' (' + Normalizer.shortComp(r.comp) + ').');
        c.provisional = true;
        return r2(Math.max(0, r.m));
      }
      if (r.s < 0) note(label + ' con saldo negativo (' + ars(r.s) + '); se toma $0.', 'warn');
      else if (r.s === 0) note(label + ' sin saldo pendiente (Saldo Comp. = $0).');
      return r2(Math.max(0, r.s));
    };
    if (!row.mainDoc) {
      missing = true;
      const nf = row.src && /no\s*factur/i.test(row.src.estadoFactura || '');
      if (row.compNone) flag('error', nf ? 'SIN COMPROBANTE / NO FACTURADO' : 'SIN COMPROBANTE / NO ENCONTRADO', 'El operador indicó que ningún comprobante corresponde. Monto pendiente.');
      else if (row.auto && ComprobanteMatcher.candidates(row).length) flag('error', 'SIN COMPROBANTE EN INFORME', 'El pedido ' + row.mainOrder + ' no trae Factura/NDP en el informe. Hay posibles comprobantes en Saldo Comprobante: elegí uno o indicá que ninguno corresponde.');
      else flag('error', nf ? 'SIN COMPROBANTE / NO FACTURADO' : 'SIN COMPROBANTE / NO ENCONTRADO', row.mainOrder ? 'El pedido ' + row.mainOrder + ' no trae Factura/NDP y no se encontraron comprobantes posibles. Monto pendiente.' : 'Falta el comprobante principal.');
    } else {
      mainR = FinancialIndex.findComp(row.mainDoc, row.cliente);
      if (!mainR) { missing = true; flag('error', 'SALDO NO ENCONTRADO', 'El comprobante ' + Normalizer.shortComp(row.mainDoc) + ' no figura en Saldo Comprobante.'); }
    }
    if (row.hasShip) {
      if (!row.shipDoc) { missing = true; flag('error', 'SIN COMPROBANTE / NO FACTURADO', 'El pedido de envío no tiene NDP.'); }
      else {
        shipR = FinancialIndex.findComp(row.shipDoc, row.cliente);
        if (!shipR) {
          // NDP de envío que no está en Saldo Comprobante: costo del pedido como MONTO PROVISORIO, a confirmar por el operador
          const det = r2(row.shipCostManual ? (row.shipCost || 0) : (row.shipCostOrig != null ? row.shipCostOrig : (row.shipCost || 0)));
          if (det > 0) {
            const sc = ShipConfirm.state(row, det);
            c.shipProv = { detected: det, amount: sc.amount, status: sc.status };
            if (sc.status === 'PENDING_CONFIRMATION') flag('warn', 'ENVÍO A CONFIRMAR', 'El pedido de envío ' + row.shipOrder + ' tiene un costo de ' + ars(det) + '. La NDP ' + Normalizer.shortComp(row.shipDoc) + ' no aparece en Saldo Comprobante. Por ahora se toma ' + ars(det) + ' como costo del envío; antes de la hoja final hay que confirmarlo.');
            else note('Envío ' + (sc.status === 'MODIFIED_CONFIRMED' ? 'modificado y confirmado' : 'confirmado') + ' por el operador: ' + ars(sc.amount) + (sc.reason ? ' (' + sc.reason + ')' : '') + '.', 'ok');
          } else { missing = true; flag('error', 'SALDO NO ENCONTRADO', 'La NDP de envío ' + Normalizer.shortComp(row.shipDoc) + ' no figura en Saldo Comprobante.'); }
        } else if (row.shipConfirm || row.shipProvSeen) {
          // La NDP apareció después: si coincide se resuelve sola; si difiere, se revisa (no se pisa en silencio)
          const prev = row.shipConfirm ? row.shipConfirm.amount : r2(row.shipCostOrig || 0);
          const real = r2(Math.max(0, shipR.s || 0));
          if (Math.abs(real - prev) > (Number(Config.get().tolerance) || 1) && !row.shipUseReal && row.shipKeepDiff !== real) {
            c.shipProv = { detected: prev, amount: prev, status: 'DIFFERENCE', real };
            flag('warn', 'DIFERENCIA ENTRE COSTO DE ENVÍO Y SALDO COMPROBANTE · REVISAR', 'Saldo Comprobante trae la NDP ' + Normalizer.shortComp(row.shipDoc) + ' con ' + ars(real) + ' y el envío estaba en ' + ars(prev) + '. Se mantiene ' + ars(prev) + ' hasta que lo resuelvas.');
          } else if (row.shipKeepDiff === real && !row.shipUseReal) { c.shipProv = { detected: prev, amount: prev, status: 'KEPT' }; note('Se mantiene el envío en ' + ars(prev) + ' (Saldo Comprobante: ' + ars(real) + ').', 'warn'); }
          else note('La NDP de envío ya figura en Saldo Comprobante (' + ars(real) + '): se usa el saldo real.', 'ok');
        }
      }
    }
    if (mainR) c.mainDue = dueOf(mainR, 'Comprobante principal');
    if (shipR && !(c.shipProv && ['DIFFERENCE', 'KEPT'].includes(c.shipProv.status))) c.shipDue = dueOf(shipR, 'NDP de envío');
    else if (c.shipProv) { c.shipDue = c.shipProv.amount; row.shipProvSeen = true; }
    const ref = mainR || shipR;
    const ccRec = FinancialIndex.findCC(ref ? ref.cuit : '', row.cliente);
    c.ccRec = ccRec ? { c: ccRec.c, f: ccRec.f, s: ccRec.s, loc: ccRec.loc, cuit: ccRec.cuit } : null;
    if (ccRec) c.cc = r2(ccRec.s || 0);
    c.cuit = (ref && ref.cuit) || (ccRec && ccRec.cuit) || '';
    if (missing) {
      note('Sin saldo de comprobante confirmado no se calcula importe: el monto queda pendiente (nunca $0).', 'error');
      return c;
    }
    c.target = r2((c.mainDue || 0) + (row.hasShip ? (c.shipDue || 0) : 0));
    if (!ccRec) {
      flag('error', 'REVISAR', 'El cliente no se encontró en Saldo Cuenta Corriente (o hay más de un cliente posible): no se puede controlar el tope de cobro.');
      return c;
    }
    if (ref.cuit && ccRec.cuit && ref.cuit !== ccRec.cuit) {
      flag('error', 'REVISAR', 'El CUIT del comprobante (' + ref.cuit + ') no coincide con el de la cuenta corriente (' + ccRec.cuit + ').');
      return c;
    }
    if (FinancialIndex.scVersion < 2) note('Saldo Comprobante se cargó con una versión anterior: volvé a cargarlo para detectar "Saldo Anterior".', 'warn');
    c.key = ccRec.cuit || Normalizer.name(ccRec.c);
    const cr = this.credits(ref.key);
    c.oldIdentified = cr.old; c.validReflected = cr.valid; c.undated = cr.undated;
    c.sa = FinancialIndex.saByClient.get(ref.key) || 0;
    c.recon = { sumVisible: cr.visible, diff: r2(c.cc - cr.visible), consistent: Math.abs(c.cc - cr.visible) <= (Number(cfg.tolerance) || 0) };
    c.movements = cr.list.map(m => Object.assign({}, m, {
      age: this.ageText(m.d),
      motivo: m.cat === 'old' ? 'Antiguo (> ' + cfg.creditMonths + ' meses): se excluye, se suma al saldo CC' : m.cat === 'valid' ? 'Vigente: ya reflejado en la cuenta corriente' : 'Sin fecha: no modifica el tope'
    }));
    c.refKey = ref.key; c.creditsAll = cr.list;
    const allowedT = new Set((cfg.creditTypes || ['NOC', 'REC', 'REP']).map(t => String(t).toUpperCase()));
    const ignored = FinancialIndex.clientRows(ref.key).filter(r => r.s != null && r.s < -0.004 && !allowedT.has(r.t));
    if (ignored.length) note('Comprobantes con saldo negativo que no son de un tipo de crédito autorizado (' + ignored.slice(0, 4).map(r => Normalizer.shortComp(r.comp) + ' ' + ars(r.s)).join('; ') + (ignored.length > 4 ? '…' : '') + '): no se toman como saldo a favor.', 'warn');
    c.docNs = [mainR && mainR.n, shipR && shipR.n].filter(Boolean);
    c.docDates = [mainR && mainR.d, shipR && shipR.d].filter(Boolean);
    c.sortDate = (mainR && mainR.d) || (shipR && shipR.d) || '9999';
    c.sortComp = (mainR && mainR.n) || (shipR && shipR.n) || '';
    c.ready = true;
    return c;
  },
  /* Regla de cobro (v15):
     · CC ≥ comprobantes de la entrega → se cobran solo los comprobantes.
     · CC < comprobantes → la CC es el TOPE REAL de cobro.
     · Única excepción: créditos ANTIGUOS (fecha > límite) comprobados como todavía incluidos en la CC.
       Comprobado = los movimientos de Saldo Comprobante reconstruyen la CC, o el operador lo confirmó.
       Si no se puede comprobar: REVISAR CRÉDITO ANTIGUO y el monto se queda en la CC.
     · Los créditos vigentes ya están dentro de la CC: solo explican la diferencia, no se descuentan otra vez.
     · Saldo Anterior: no se usa. Sin regla de "entrega anterior". */
  oldKey(clientKey, m) { return clientKey + '|' + Normalizer.comp(m.comp); },
  allocate(list) {
    const c0 = list[0].calc, cfg = Config.get(), tol = Number(cfg.tolerance) || 0;
    const totalTarget = r2(list.reduce((s, r) => s + r.calc.target, 0));
    const all = c0.creditsAll || [];
    const consistent = !!(c0.recon && c0.recon.consistent);
    const dec = RouteStore.oldDecisions || {};
    const old = all.filter(x => x.cat === 'old').map(x => {
      const k = this.oldKey(c0.refKey, x), d = dec[k];
      return Object.assign({}, x, { key: k, decision: d || (consistent ? 'auto' : '') });
    });
    const covered = c0.cc >= totalTarget - tol;
    const proven = old.filter(x => x.decision === 'auto' || x.decision === 'include');
    const pending = covered ? [] : old.filter(x => !x.decision);
    const provenSum = r2(proven.reduce((s, x) => s + x.amt, 0));
    const adjusted = r2(c0.cc + (covered ? 0 : provenSum));
    const collectTotal = r2(Math.min(totalTarget, Math.max(0, adjusted)));
    const reduction = r2(totalTarget - collectTotal);
    const oldExcluded = covered ? 0 : r2(Math.max(0, Math.min(provenSum, totalTarget - c0.cc)));
    const validSum = r2(all.filter(x => x.cat === 'valid').reduce((s, x) => s + x.amt, 0));
    // Saldo a favor IDENTIFICADO: créditos vigentes con importe y fecha, del más reciente al más viejo,
    // hasta cubrir la reducción. Lo que no se explica con movimientos no se llama "saldo a favor".
    // Del más reciente al más viejo se toman créditos COMPLETOS mientras entren en la diferencia;
    // el primero que no entra corta la búsqueda (solo el más reciente puede usarse en parte).
    // Así un recibo viejo enorme que figura "abierto" no se presenta como saldo a favor.
    // Solo se puede afirmar que estos créditos están dentro de la CC si los movimientos visibles la reconstruyen.
    const favorProven = consistent;
    const favorUsed = []; let need = covered || !favorProven ? 0 : reduction, stop = false;
    all.filter(x => x.cat === 'valid').slice().sort((a, b) => (b.d || '').localeCompare(a.d || '') || b.comp.localeCompare(a.comp)).forEach((x, i) => {
      if (stop || need <= 0.004) return;
      if (x.amt <= need + 0.004) { favorUsed.push(Object.assign({}, x, { used: x.amt, part: false })); need = r2(need - x.amt); }
      else if (i === 0) { favorUsed.push(Object.assign({}, x, { used: need, part: true })); need = 0; }
      else stop = true;
    });
    const favorTotal = r2(favorUsed.reduce((s, x) => s + x.used, 0));
    const unexplained = covered ? 0 : r2(Math.max(0, reduction - favorTotal));
    const unprovenRecent = covered || favorProven ? [] : all.filter(x => x.cat === 'valid').slice().sort((a, b) => (b.d || '').localeCompare(a.d || '')).slice(0, 3);
    const nDocs = list.reduce((n, r) => n + r.calc.docNs.length, 0);
    const movs = all.map(x => {
      const o = old.find(y => y.comp === x.comp && y.d === x.d);
      return Object.assign({}, x, {
        age: this.ageText(x.d), key: o ? o.key : '', decision: o ? o.decision : '',
        motivo: x.cat === 'valid' ? 'Vigente: ya está dentro de la cuenta corriente (no se descuenta otra vez)'
          : x.cat === 'undated' ? 'Sin fecha: no modifica el cobro'
          : o.decision === 'auto' ? 'Antiguo, comprobado en la CC (los movimientos la reconstruyen): se excluye'
          : o.decision === 'include' ? 'Antiguo, confirmado por el operador: se excluye y se cobra'
          : o.decision === 'used' ? 'Antiguo, marcado como ya utilizado: no cambia el cobro'
          : 'Antiguo sin comprobar: REVISAR (no aumenta el cobro)'
      });
    });
    let left = reduction;
    list.slice().sort((a, b) => a.calc.sortDate.localeCompare(b.calc.sortDate) || a.calc.sortComp.localeCompare(b.calc.sortComp) || String(a.id).localeCompare(String(b.id)))
      .forEach(row => {
        const c = row.calc;
        const red = r2(Math.min(c.target, left)); left = r2(left - red);
        // Prioridad del envío: la reducción se aplica primero a la mercadería
        c.mainCollect = r2(Math.max(0, (c.mainDue || 0) - red));
        c.shipCollect = row.hasShip ? r2(Math.max(0, (c.shipDue || 0) - Math.max(0, red - (c.mainDue || 0)))) : 0;
        c.suggested = r2(c.mainCollect + c.shipCollect);
        Object.assign(c, { applicable: c.suggested, groupSize: list.length, reduction: red, totalTarget, adjusted, collectTotal, oldExcluded, oldPending: pending.map(x => x.comp), unexplained, validSum, movements: movs, gap: unexplained, covered });
        if (list.length > 1) c.notes.push({ level: 'warn', text: 'El cliente tiene ' + list.length + ' entregas en la hoja: el tope de cuenta corriente se reparte entre todas, reduciendo primero el comprobante más antiguo.' });
        if (Math.abs(c.sa) > 0.004) c.notes.push({ level: 'info', text: 'Saldo anterior sin detalle (' + ars(c.sa) + '): queda fuera de cualquier ajuste. La cuenta corriente es el control.' });
        if (covered) { c.summary = nDocs > 1 ? 'SE COBRA SOLO ESTA ENTREGA' : 'SE COBRA SOLO ESTE COMPROBANTE'; c.notes.push({ level: 'ok', text: c.summary + '. La cuenta corriente (' + ars(c0.cc) + ') puede incluir otras deudas.' }); return; }
        if (pending.length) c.flags.push({ level: 'warn', code: 'REVISAR CRÉDITO ANTIGUO', text: 'Créditos de más de ' + cfg.creditMonths + ' meses visibles en Saldo Comprobante (' + pending.map(x => x.comp + ' ' + ars(x.amt)).join('; ') + ') sin comprobar que sigan dentro de la cuenta corriente. No aumentan el cobro hasta que confirmes en el detalle si deben excluirse.' });
        if (oldExcluded > 0.004) c.flags.push({ level: 'old', code: 'CRÉDITO ANTIGUO EXCLUIDO', text: 'NO SE TOMA SALDO A FAVOR: créditos de más de ' + cfg.creditMonths + ' meses (' + ars(oldExcluded) + ') no reducen el cobro.' });
        c.favor = favorUsed; c.favorTotal = favorTotal; c.unexplained = unexplained;
        const favTxt = favorTotal > 0.004 ? 'SE TOMA SALDO A FAVOR: ' + ars(favorTotal) + ' (' + favorUsed.map(x => Normalizer.shortComp(x.comp) + ' del ' + isoToDMY(x.d) + (x.part ? ' · ' + ars(x.used) + ' de ' + ars(x.amt) : '')).join(' + ') + ')' : '';
        if (reduction > 0.004) {
          if (unexplained > tol) {
            c.summary = 'TOTAL A COBRAR SEGÚN CUENTA CORRIENTE: ' + ars(collectTotal);
            c.flags.push({ level: 'soft', code: 'LISTO CON ADVERTENCIA', text: c.summary + '.' + (favTxt ? ' ' + favTxt + '.' : '') + ' Hay una diferencia de ' + ars(unexplained) + ' sin movimiento comprobado: no cambia el monto a cobrar.' });
            if (unprovenRecent.length) c.notes.push({ level: 'info', text: 'Créditos recientes abiertos en Saldo Comprobante (' + unprovenRecent.map(x => Normalizer.shortComp(x.comp) + ' ' + ars(x.amt) + ' del ' + isoToDMY(x.d)).join('; ') + ') no se muestran como saldo a favor: no se puede comprobar que estén reflejados en la cuenta corriente (los movimientos visibles suman ' + ars(c0.recon ? c0.recon.sumVisible : 0) + ' y la CC es ' + ars(c0.cc) + ').' });
          } else {
            c.summary = favTxt;
            c.flags.push({ level: 'good', code: 'SE TOMA SALDO A FAVOR', text: favTxt + '. Se cobra ' + ars(collectTotal) + ' en lugar de ' + ars(totalTarget) + '.' });
          }
        }
        if (red > 0 && row.hasShip) c.notes.push({ level: 'ok', text: 'Se preserva primero el costo de envío; la reducción de ' + ars(red) + ' se aplica a la mercadería.' });
        if (c.suggested === 0 && c.target > 0) c.notes.push({ level: 'ok', text: 'El saldo de cuenta corriente (' + ars(c0.cc) + ') cubre toda la deuda: no corresponde cobrar.' });
      });
  }
};
function sameMoney(a, b) { if (a == null || b == null) return a == b; return Math.abs(a - b) < 0.005; }

/* ---------------- RouteStore (estado + persistencia) ---------------- */
/* ---------------- Envío provisorio: confirmación del operador (Fase 2A.1) ---------------- */
const ShipConfirm = {
  bridge() { return window.OKD_BRIDGE && window.OKD_BRIDGE.shipping; },
  fp(row, det) { return [row.shipOrder, Normalizer.comp(row.shipDoc), r2(det), row.mainOrder, row.transportista, FinancialIndex.importId || ''].join('|'); },
  // Estado vigente; si cambió NDP, pedido, costo, asociación, transportista o importación → vuelve a PENDIENTE
  state(row, det) {
    const fp = this.fp(row, det);
    if (row.shipConfirm && row.shipConfirm.fp === fp) return row.shipConfirm;
    if (row.shipConfirm) {
      row.shipConfirmPrev = row.shipConfirm; row.shipConfirm = null;
      RouteStore.log({ tipo: 'confirmación de envío invalidada', pedido: row.mainOrder, envio: row.shipOrder });
      const b = this.bridge(); if (b && b.invalidate) b.invalidate({ sheet_key: RouteStore.sheetId, ship_order: row.shipOrder, fingerprint: fp }).catch(() => {});
    }
    return { status: 'PENDING_CONFIRMATION', amount: r2(det) };
  },
  pending() { return RouteStore.rows.filter(r => r.sale && !r.shipPending && r.calc && r.calc.shipProv && ['PENDING_CONFIRMATION', 'DIFFERENCE'].includes(r.calc.shipProv.status)); },
  async confirm(row, amount, reason, note) {
    const p = row.calc.shipProv, det = p.detected;
    const changed = Math.abs(amount - det) > 0.004;
    if (!(amount > 0)) throw new Error('El importe debe ser mayor a $ 0.');
    if (changed && !String(reason || '').trim()) throw new Error('Para cambiar el importe indicá el motivo.');
    const fp = this.fp(row, det);
    if (!RouteStore.sheetId) { RouteStore.sheetId = sheetUid(); RouteStore.save(); }
    const payload = { sheet_key: RouteStore.sheetId, ship_order: row.shipOrder, ship_doc: row.shipDoc, main_order: row.mainOrder, carrier_id: row.transportista,
      source_import_id: FinancialIndex.importId || '', detected_amount: det, confirmed_amount: r2(amount), reason: changed ? reason : null, note: note || null, fingerprint: fp };
    const b = this.bridge();
    const srv = b ? await b.confirm(payload) : { id: null, confirmed_at: new Date().toISOString(), confirmed_by: null }; // en línea: se guarda en el servidor
    row.shipConfirm = { fp, status: changed ? 'MODIFIED_CONFIRMED' : 'CONFIRMED', amount: r2(amount), detected: det, reason: changed ? reason : null, note: note || null, at: srv.confirmed_at, by: srv.confirmed_by, serverId: srv.id };
    RouteStore.log({ tipo: changed ? 'envío modificado y confirmado' : 'envío confirmado', pedido: row.mainOrder, envio: row.shipOrder, anterior: det, nuevo: r2(amount), motivo: reason || null });
  },
  resolveDifference(row, useReal) {
    if (useReal) row.shipUseReal = true; else row.shipKeepDiff = row.calc.shipProv.real;
    RouteStore.log({ tipo: 'diferencia de envío resuelta', pedido: row.mainOrder, envio: row.shipOrder, decision: useReal ? 'usar saldo real' : 'mantener importe' });
  },
  renderBar() {
    let bar = document.getElementById('shipBar');
    const wrap = document.getElementById('tablewrap'); if (!wrap) return;
    if (!bar) { bar = document.createElement('div'); bar.id = 'shipBar'; bar.className = 'shipbar'; wrap.parentNode.insertBefore(bar, wrap); }
    const n = this.pending().length;
    bar.hidden = !n;
    if (n) {
      bar.innerHTML = '<b>⚠ ' + n + (n === 1 ? ' ENVÍO PARA CONFIRMAR' : ' ENVÍOS PARA CONFIRMAR') + '</b><span>Podés seguir trabajando. Antes del PDF, Excel o impresión final te vamos a pedir que lo confirmes.</span><button class="btn soft" type="button" id="shipReview">REVISAR AHORA</button>';
      bar.querySelector('#shipReview').onclick = () => this.open(null);
    }
  },
  // Salida final: si hay envíos sin confirmar, primero el asistente
  guard(action, run) { if (this.pending().length) this.open(action, run); else run(); },
  open(action, run) {
    const old = document.getElementById('shipModal'); if (old) old.remove();
    const m = document.createElement('div'); m.className = 'modal open'; m.id = 'shipModal';
    const items = this.pending();
    const card = r => {
      const p = r.calc.shipProv;
      if (p.status === 'DIFFERENCE') return '<div class="shipitem" data-id="' + r.id + '"><b>Envío ' + esc(r.shipOrder) + ' · ' + esc(r.cliente) + '</b>' +
        '<p>Saldo Comprobante ahora trae la NDP ' + esc(Normalizer.shortComp(r.shipDoc)) + ' con <b>' + ars(p.real) + '</b>, pero el envío estaba en <b>' + ars(p.amount) + '</b>.</p>' +
        '<div class="shipacts"><button class="btn dark" type="button" data-a="real">USAR ' + ars(p.real) + '</button><button class="btn soft" type="button" data-a="keep">MANTENER ' + ars(p.amount) + '</button></div></div>';
      const tarifa = (Config.get().shipCosts[r.shipGroup || 'ESTE'] || []).map(ars).join(' / ');
      return '<div class="shipitem" data-id="' + r.id + '"><b>Envío ' + esc(r.shipOrder) + ' · ' + esc(r.cliente) + '</b>' +
        '<p>El pedido de envío ' + esc(r.shipOrder) + ' tiene un costo de <b>' + ars(p.detected) + '</b>.<br>La NDP ' + esc(Normalizer.shortComp(r.shipDoc)) + ' no aparece en Saldo Comprobante.<br>Por ahora vamos a tomar ' + ars(p.detected) + ' como costo del envío.</p>' +
        (tarifa ? '<p class="shipnote">Tarifa configurada para la zona: ' + tarifa + '</p>' : '') +
        '<div class="shipacts"><button class="btn dark" type="button" data-a="ok">SÍ, CONFIRMAR ' + ars(p.detected) + '</button><button class="btn soft" type="button" data-a="edit">CAMBIAR IMPORTE</button></div>' +
        '<div class="shipedit" hidden><label>Nuevo importe <input class="ed" data-f="amt" inputmode="decimal"></label><label>Motivo (obligatorio) <input class="ed" data-f="reason"></label><label>Nota <input class="ed" data-f="note"></label><button class="btn dark" type="button" data-a="save">GUARDAR</button></div>' +
        '<div class="shiperr" hidden></div></div>';
    };
    m.innerHTML = '<div class="dialog" role="dialog" aria-modal="true"><header><b>REVISÁ LOS COSTOS DE ENVÍO</b></header><div class="body" id="shipList">' + items.map(card).join('') + '</div>' +
      '<footer><button class="btn ghost" type="button" id="shipBack">VOLVER A REVISAR LA HOJA</button>' + (run ? '<button class="btn go" type="button" id="shipGo" disabled>CONTINUAR</button>' : '') + '</footer></div>';
    document.body.appendChild(m);
    const refresh = () => {
      CalculationEngine.computeAll(RouteStore.rows); RouteStore.save(); UI.renderTable();
      const left = this.pending().length, go = m.querySelector('#shipGo');
      if (go) go.disabled = left > 0;
      if (!left && !run) m.remove();
    };
    m.querySelector('#shipBack').onclick = () => m.remove();
    const go = m.querySelector('#shipGo'); if (go) go.onclick = () => { if (!this.pending().length) { m.remove(); run(); } };
    m.querySelectorAll('.shipitem').forEach(it => {
      const row = RouteStore.find(it.dataset.id), err = it.querySelector('.shiperr');
      const fail = e => { if (err) { err.textContent = e.message; err.hidden = false; } };
      const done = t => { it.classList.add('done'); it.querySelector('.shipacts').innerHTML = '<span class="shipok">' + t + '</span>'; const ed = it.querySelector('.shipedit'); if (ed) ed.hidden = true; refresh(); };
      it.querySelectorAll('[data-a]').forEach(b => b.onclick = async () => {
        const a = b.dataset.a;
        if (a === 'edit') { it.querySelector('.shipedit').hidden = false; return; }
        b.disabled = true; // doble clic: una sola confirmación
        try {
          if (a === 'ok') { await this.confirm(row, row.calc.shipProv.detected); done('CONFIRMADO ' + ars(row.calc.shipProv.detected)); }
          else if (a === 'save') { const v = parseMoney(it.querySelector('[data-f="amt"]').value); await this.confirm(row, v, it.querySelector('[data-f="reason"]').value, it.querySelector('[data-f="note"]').value); done('MODIFICADO Y CONFIRMADO ' + ars(v)); }
          else if (a === 'real' || a === 'keep') { this.resolveDifference(row, a === 'real'); done(a === 'real' ? 'SE USA EL SALDO REAL' : 'SE MANTIENE EL IMPORTE'); }
        } catch (e) { b.disabled = false; fail(e); }
      });
    });
  }
};

/* ---------------- Reglas financieras del servidor (RC2): pisan la configuración local y quedan en el snapshot ---------------- */
// Modo online: los campos financieros de la configuración local quedan de solo lectura (se editan en CONFIGURACIÓN → REGLAS FINANCIERAS)
function lockFinancialConfig() {
  if (window.OKD_SERVER_ROUTING) { const t = document.getElementById('cfgRules'); if (t) t.querySelectorAll('input,button').forEach(x => { x.disabled = true; }); const ad = document.getElementById('cfgAddRule'); if (ad) { ad.disabled = true; ad.title = 'Las reglas de asignación se editan en CONFIGURACIÓN → REGLAS DE ASIGNACIÓN (servidor)'; } }
  ['cfgFAC', 'cfgNDP', 'cfgEste', 'cfgAlr', 'cfgNoc', 'cfgTol'].forEach(id => { const el = document.getElementById(id); if (el) { el.disabled = true; el.title = 'Lo define Administración en CONFIGURACIÓN → REGLAS FINANCIERAS (servidor)'; } });
  const t = document.getElementById('cfgTitle'); if (t && !document.getElementById('cfgServerNote')) t.insertAdjacentHTML('afterend', '<p class="rp-note" id="cfgServerNote">Medios de pago, costos de envío, antigüedad de créditos y tolerancia vienen del servidor (versión ' + (window.OKD_RULES_VERSION || '—') + ') y son iguales para todos los operadores.</p>');
}
// Acceso del shell online a funciones del panel (abrir/quitar borradores, PDF desde snapshot)
window.OKD_LEGACY = {
  openDraft: (k, n, c) => SheetTabs.openDraft(k, n, c), dropLocal: k => SheetTabs.dropLocal(k),
  pdfBytes: model => PdfExporter.bytesFromModel(model), xlsxBytes: model => ExcelExporter.bytesFromModel(model)
};
// Reglas Estado/Zona → Transportista vigentes del servidor. Recalcula solo asignaciones AUTOMÁTICAS: una reasignación manual del Operario no se toca.
window.OKD_APPLY_ROUTING = (f) => {
  if (!f || !Array.isArray(f.rules)) return;
  window.OKD_SERVER_ROUTING = f.rules.filter(r => r.active !== false).sort((a, b) => (a.priority || 0) - (b.priority || 0)).map(r => ({ estado: r.estado, zona: r.zona || '', carrier: r.carrier }));
  window.OKD_ROUTING_VERSION = f.version; lockFinancialConfig();
  if (!Config.value || !window.OKD_BOOTED) { window.OKD_PENDING_ROUTING = f; return; }
  try { RouteStore.applyConfig(); CalculationEngine.computeAll(RouteStore.rows); RouteStore.save(); UI.renderTable(); } catch (e) { console.warn('reglas de asignación', e); }
};
window.OKD_APPLY_RULES = (f) => {
  if (!f || !f.rules) return;
  window.OKD_SERVER_RULES = JSON.parse(JSON.stringify(f.rules)); window.OKD_RULES_VERSION = f.version; lockFinancialConfig();
  if (!Config.value || !window.OKD_BOOTED) { window.OKD_PENDING_RULES = f; return; } // el panel todavía arranca: se aplican al terminar
  Config.get();
  try { RouteStore.applyConfig(); CalculationEngine.computeAll(RouteStore.rows); RouteStore.save(); UI.renderTable(); } catch (e) { console.warn('reglas', e); } // medios de pago, costos, créditos y tolerancia recalculados
};

/* ---------------- Financiación propia del cliente (RC2.1b): planes persistidos en el servidor ---------------- */
const FinancingPlans = {
  byClient: new Map(), state: 'OK', error: '', failedKeys: new Set(), localKeys: new Set(), promise: null,
  bridge() { return window.OKD_BRIDGE && window.OKD_BRIDGE.financing; },
  store(plans) { (plans || []).forEach(p => { const l = (this.byClient.get(p.client_key) || []).filter(x => x.id !== p.id); l.push(p); this.byClient.set(p.client_key, l); }); },
  setState(st, err) {
    this.state = st; this.error = err || '';
    const el = document.getElementById('finSync'); if (!el) return;
    el.hidden = st === 'OK' && !this.lastRun; el.className = 'finsync ' + st;
    el.innerHTML = st === 'SINCRONIZANDO' ? 'FINANCIACIÓN PROPIA · SINCRONIZANDO…' : st === 'ERROR' ? '<b>FINANCIACIÓN PROPIA · REVISAR</b> · no se pudo verificar la financiación con el servidor (' + esc(err) + '). No se puede aplicar NOC a financiación ni publicar hojas de esos clientes. <button type="button" class="btn soft" id="finRetry">REINTENTAR</button>' : 'FINANCIACIÓN PROPIA · OK';
    const rb = document.getElementById('finRetry'); if (rb) rb.onclick = () => this.retry();
  },
  // Se llama al terminar de procesar el Saldo Comprobante. La promesa queda guardada y todo lo que depende de la financiación la espera.
  sync(groups, importId) {
    const b = this.bridge(); if (!b || !window.OKFinancing.planCandidates) return Promise.resolve();
    this.lastGroups = groups; this.lastImport = importId; this.lastRun = true;
    this.promise = (async () => {
      this.setState('SINCRONIZANDO');
      // claves de clientes con financiación detectada localmente (para saber a quién afecta una falla)
      const loc = new Set(); groups.forEach(list => list.forEach(g => { if (g.fin && g.fin.status !== 'NORMAL') loc.add(g.key); }));
      try {
        const keys = new Set((await b.keys()).map(k => k.client_key + '||' + k.comp));
        keys.forEach(k => loc.add(k.split('||')[0]));
        const c = window.OKFinancing.planCandidates(groups, importId, keys);
        if (c.length) this.store(await b.sync(importId || '', c));
        this.failedKeys = new Set(); this.localKeys = loc; this.setState('OK');
      } catch (e) { this.failedKeys = loc; this.localKeys = loc; this.setState('ERROR', String(e.message || e)); }
      if (this.state === 'OK' && this.readFailed.size) this.setState('ERROR', 'planes sin verificar');
    })();
    return this.promise;
  },
  async ready() { if (this.promise) await this.promise; },
  // ¿Este cliente depende de una sincronización fallida?
  blocked(key) { return (this.state === 'ERROR' && this.failedKeys.has(key)) || this.readFailed.has(key); },
  readFailed: new Set(),
  // Una falla de lectura NO equivale a "sin planes": esos clientes quedan en REVISAR (no se aplica NOC a financiación ni se publica) hasta reintentar.
  async forClients(keys) {
    await this.ready();
    const b = this.bridge(); keys = [...new Set(keys.filter(Boolean))]; if (!b || !keys.length) return [];
    try {
      const l = await b.forClients(keys);
      keys.forEach(k => { this.readFailed.delete(k); this.byClient.set(k, []); }); this.store(l);   // limpia solo lo consultado con éxito
      if (this.state === 'ERROR' && !this.readFailed.size && !this.failedKeys.size) this.setState('OK');
      return l;
    } catch (e) {
      keys.forEach(k => this.readFailed.add(k)); this.lastReadKeys = keys; this.setState('ERROR', 'no se pudieron leer los planes: ' + (e.message || e));
      return null;
    }
  },
  async retry() {
    if (this.failedKeys.size && this.lastGroups) await this.sync(this.lastGroups, this.lastImport);
    if (this.readFailed.size) await this.forClients([...this.readFailed]);
  },
  active(key) { return (this.byClient.get(key) || []).filter(p => p.status === 'ACTIVO' && Number(p.operational_pending) > 0.004); },
  freqLabel(f) { return f === 'POR_CONFIRMAR' ? 'POR CONFIRMAR' : f; }
};
function nocReconLabel(st) { return { OK: 'Sin diferencias', PENDING_CIANBOX: 'Pendiente de Cianbox', CANCELLED_ROUTE_REVIEW: 'Hoja cancelada — revisar', RECONCILED: 'Conciliada', REVERSED: 'Revertida', CIANBOX_DIFFERENCE: 'Diferencia detectada' }[st] || st || ''; }
window.OKD_NOC_LABEL = nocReconLabel;
// RC3: conciliación de las NOC conocidas contra el Saldo Comprobante importado (Cianbox informa; nunca borra aplicaciones locales)
const NocReconcile = {
  async run(importId) {
    const b = window.OKD_BRIDGE && window.OKD_BRIDGE.noc; if (!b || !b.reconcile) return;
    const items = [];
    FinancialIndex.byClient.forEach(list => list.forEach(r => { if (/^\s*NOC\b/i.test(r.comp || '') && r.m != null) items.push({ comp: r.comp, cuit: r.cuit || '', issued_date: r.d || '', original_amount: Math.abs(r.m), available_amount: Math.max(0, -(r.s || 0)) }); }));
    if (!items.length) return;   // sin NOC en el archivo no hay evidencia para conciliar (nunca se marca "no informada" con un archivo vacío)
    const el = document.getElementById('nocSync');
    try { const res = await b.reconcile(importId || '', items, true); if (el) { el.hidden = true; } this.last = res; }
    catch (e) { if (el) { el.hidden = false; el.className = 'finsync ERROR'; el.innerHTML = '<b>CONCILIACIÓN NOC · REVISAR</b> · no se pudo conciliar con el Saldo Comprobante (' + esc(e.message || e) + '). <button type="button" class="btn soft" id="nocRetry">REINTENTAR</button>'; document.getElementById('nocRetry').onclick = () => this.run(importId); } }
  }
};
const rowKey = r => (r.calc && r.calc.refKey) || (r.calc && r.calc.cuit) || Normalizer.name(r.cliente);

/* ---------------- Hojas múltiples: cada pestaña = una hoja/borrador independiente (Fase 2B.1) ---------------- */
// "3 paradas · 9 bultos" de la hoja activa
function sheetSummary(rows) {
  rows = (rows || RouteStore.rows).filter(r => r.sale);
  const b = rows.reduce((a, r) => a + (parseInt(r.bultos, 10) || 0), 0);
  return rows.length + ' parada' + (rows.length === 1 ? '' : 's') + ' · ' + b + ' bulto' + (b === 1 ? '' : 's');
}
const SheetTabs = {
  idx: null,
  async boot() {
    this.idx = await DB.get('sheets_index');
    if (!this.idx) { // migra la hoja única anterior a la primera pestaña
      const old = await DB.get('sheet'); const id = (old && old.sheetId) || sheetUid();
      this.idx = { active: id, tabs: [{ id, name: 'Hoja 1', closed: false, orders: [] }] };
      if (old) await DB.set('sheet:' + id, Object.assign({}, old, { sheetId: id }));
      await DB.set('sheets_index', this.idx);
    }
    return (await DB.get('sheet:' + this.idx.active)) || { sheetId: this.idx.active };
  },
  apply(sheet) {
    sheet = sheet || {};
    RouteStore.rows = sheet.rows || []; RouteStore.selected = new Set(sheet.selected || []); RouteStore.sheetId = sheet.sheetId || sheetUid(); RouteStore.sheetDate = sheet.sheetDate || '';
    RouteStore.audit = sheet.audit || []; RouteStore.showCash = sheet.showCash !== false; RouteStore.showCheques = sheet.showCheques !== false; RouteStore.showTransfers = sheet.showTransfers !== false;
    RouteStore.oldDecisions = sheet.oldDecisions || {}; RouteStore.published = sheet.published || null;
  },
  tab(id) { return this.idx && this.idx.tabs.find(t => t.id === (id || RouteStore.sheetId)); },
  touch() {
    if (!this.idx) return;
    let t = this.tab(); if (!t) { t = { id: RouteStore.sheetId, name: 'Hoja ' + (this.idx.tabs.length + 1), closed: false, orders: [] }; this.idx.tabs.push(t); }
    t.orders = RouteStore.rows.flatMap(r => [r.mainOrder, r.shipOrder]).filter(Boolean).map(String);
    t.published = RouteStore.published ? RouteStore.published.number : null;
    this.idx.active = RouteStore.sheetId;
    DB.set('sheets_index', this.idx);
    this.sync(t);
  },
  sync(t) {
    const b = window.OKD_BRIDGE && window.OKD_BRIDGE.drafts; if (!b || RouteStore.published || !RouteStore.rows.length) return;
    clearTimeout(this._st); const id = RouteStore.sheetId, rows = RouteStore.rows.filter(r => r.sale);
    const content = { rows: RouteStore.rows, selected: [...RouteStore.selected], sheetDate: RouteStore.sheetDate, oldDecisions: RouteStore.oldDecisions, showCash: RouteStore.showCash, showCheques: RouteStore.showCheques, showTransfers: RouteStore.showTransfers };
    const carriers = [...new Set(rows.map(r => r.transportista).filter(Boolean))].join(' / ');
    this._st = setTimeout(() => b.touch(id, t.name, carriers, rows.length, t.orders, JSON.parse(JSON.stringify(content))).catch(() => null), 600);
  },
  rename(id) {
    const t = this.tab(id); if (!t) return;
    const n = prompt('Nombre de la hoja', t.name); if (!n || !n.trim()) return;
    t.name = n.trim().slice(0, 40); DB.set('sheets_index', this.idx); this.render(); if (id === RouteStore.sheetId) this.sync(t);
  },
  // Abre un borrador (propio o, con permiso, de otro operador) desde BORRADORES o desde un conflicto de pedido
  async openDraft(key, name, content) {
    if (this.tab(key)) { await this.switchTo(key); return; }
    await RouteStore.flush();
    this.idx.tabs.push({ id: key, name: name || 'Borrador', closed: false, orders: [] });
    await this.show(key, Object.assign({}, content || {}, { sheetId: key })); await RouteStore.flush();
  },
  // Borrador eliminado en el servidor: se quita del equipo (no toca hojas publicadas)
  async dropLocal(key) {
    const t = this.tab(key); if (!t || t.published) return;
    this.idx.tabs = this.idx.tabs.filter(x => x.id !== key); await DB.set('sheet:' + key, null);
    if (RouteStore.sheetId === key) { const o = this.idx.tabs.find(x => !x.closed); if (o) await this.show(o.id); else await this.create(); }
    else { await DB.set('sheets_index', this.idx); this.render(); }
  },
  // Pedido ya cargado en OTRA hoja borrador (no publicada)
  orderInOther(id) { const t = (this.idx ? this.idx.tabs : []).find(x => x.id !== RouteStore.sheetId && !x.published && (x.orders || []).includes(String(id))); return t ? t.name : null; },
  async show(id, sheet) {
    this.apply(sheet || (await DB.get('sheet:' + id)) || { sheetId: id });
    if (!RouteStore.sheetDate) RouteStore.sheetDate = RouteStore.rows.length ? (RouteStore.rows[0].fecha || todayISO()) : todayISO();
    this.idx.active = id; const t = this.tab(id); if (t) t.closed = false;
    await DB.set('sheets_index', this.idx);
    CalculationEngine.computeAll(RouteStore.rows);
    $('#sheetDate').value = isoToDMY(RouteStore.sheetDate); $('#optCash').checked = RouteStore.showCash; $('#optCheques').checked = RouteStore.showCheques; $('#optTransfers').checked = RouteStore.showTransfers;
    $('#log').innerHTML = ''; UI.renderTable(); this.render(); Publisher.render();
  },
  async switchTo(id) { if (id === RouteStore.sheetId) return; await RouteStore.flush(); await this.show(id); },
  async create() {
    await RouteStore.flush();
    const id = sheetUid(), n = this.idx.tabs.length + 1;
    this.idx.tabs.push({ id, name: 'Hoja ' + n, closed: false, orders: [] });
    await this.show(id, { sheetId: id }); await RouteStore.flush();
  },
  // Cerrar la pestaña NO borra el borrador: se puede reabrir
  async close(id) {
    const t = this.tab(id); if (!t) return;
    t.closed = true;
    if (id === RouteStore.sheetId) {
      await RouteStore.flush();
      const other = this.idx.tabs.find(x => !x.closed);
      if (other) await this.show(other.id); else await this.create();
    } else { await DB.set('sheets_index', this.idx); this.render(); }
  },
  render() {
    const el = document.getElementById('sheetTabs'); if (!el || !this.idx) return;
    const open = this.idx.tabs.filter(t => !t.closed), closed = this.idx.tabs.filter(t => t.closed);
    el.innerHTML = open.map(t => '<span class="stab' + (t.id === RouteStore.sheetId ? ' on' : '') + '" data-tab="' + t.id + '"><b>' + esc(t.name) + '</b>' + (t.published ? '<i>' + esc(t.published) + '</i>' : '') + '<button type="button" class="stx" data-close="' + t.id + '" title="Cerrar pestaña (no borra)">×</button></span>').join('') +
      '<button class="btn soft" type="button" id="tabNew">+ NUEVA HOJA</button>' +
      (closed.length ? '<select id="tabReopen"><option value="">Reabrir borrador…</option>' + closed.map(t => '<option value="' + t.id + '">' + esc(t.name) + '</option>').join('') + '</select>' : '') +
      '<span class="sheetsum" id="sheetSummary">' + sheetSummary() + '</span>';
    el.querySelectorAll('.stab').forEach(b => { b.addEventListener('click', e => { if (!e.target.closest('[data-close]')) this.switchTo(b.dataset.tab); }); b.addEventListener('dblclick', () => this.rename(b.dataset.tab)); b.title = 'Doble clic para renombrar'; });
    el.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => this.close(b.dataset.close)));
    el.querySelector('#tabNew').addEventListener('click', () => this.create());
    const ro = el.querySelector('#tabReopen'); if (ro) ro.addEventListener('change', () => ro.value && this.switchTo(ro.value));
  }
};

/* ---------------- Publicar hoja (Fase 2B.1): valida en el servidor, correlativo, snapshot y notificación ---------------- */
const Publisher = {
  _renderSeq: 0,
  bridge() { return window.OKD_BRIDGE && window.OKD_BRIDGE.routes; },
  carrierMatch(carriers, value) {
    const v = Normalizer.name(value || '');
    return (carriers || []).find(c => Normalizer.name(c.name) === v || Normalizer.name(c.id) === v) || null;
  },
  actionNames() {
    const rows = this.rows();
    return rows.length ? [...new Set(rows.map(r => r.transportista).filter(Boolean))] : Array.from(RouteStore.selected || []).filter(Boolean);
  },
  zone(row, carrier) {
    if (carrier.id === 'CT-ESTE') return 'ESTE';
    if (carrier.id === 'CT-ALR') return /capital|ciudad de mendoza|centro/i.test((row.localidad || '') + ' ' + (row.domicilio || '')) ? 'CENTRO' : 'ALREDEDORES';
    return null;
  },
  rows() { return RouteStore.rows.filter(r => r.sale && !r.shipPending); },
  // NOC: nunca automáticas. Se listan las NOC del Saldo Comprobante y el operador decide APLICAR (el servidor controla piso CC, remanente y consumo único).
  nocList(r) { return ((r.calc && r.calc.creditsAll) || []).filter(x => String(x.t || '').toUpperCase() === 'NOC' && x.amt > 0.004); },
  // PEDIDO ACTUAL y FINANCIACIÓN PROPIA ACTIVA, separados (nunca se mezclan los saldos)
  finHtml(rows) {
    rows = (rows || []).filter(r => r.stopType !== 'TAREA');
    const seen = new Set(), parts = [];
    rows.forEach(r => { const k = rowKey(r); if (seen.has(k)) return; seen.add(k);
      // sin verificación del servidor no se muestran saldos de planes (podrían estar desactualizados)
      if (FinancingPlans.blocked(k)) { parts.push('<div class="finrev"><b>FINANCIACIÓN PROPIA · REVISAR</b> · ' + esc(r.cliente) + ': no se pudo verificar la financiación con el servidor. Usá REINTENTAR.</div>'); return; }
      FinancingPlans.active(k).forEach(p => parts.push('<div class="finbox" data-plan="' + p.id + '"><b>CLIENTE CON FINANCIACIÓN PROPIA ACTIVA</b> · ' + esc(r.cliente) +
        '<div class="fincols"><div><span>PEDIDO ACTUAL</span><b>' + ars(rows.filter(x => rowKey(x) === k).reduce((t, x) => t + (x.monto || 0), 0)) + '</b></div>' +
        '<div><span>FINANCIACIÓN PROPIA ACTIVA · ' + esc(p.comp_label || p.comp) + '</span><b data-finsaldo>' + ars(p.operational_pending) + '</b><small>Modalidad: ' + FinancingPlans.freqLabel(p.frequency) +
        (p.next_due ? ' · Próxima cuota: ' + esc(isoToDMY(p.next_due)) + (p.next_amount ? ' ' + ars(p.next_amount) : '') : '') + ' · fuente ' + ars(p.source_pending) + (Number(p.noc_adjustments) > 0 ? ' · ajuste NOC ' + ars(p.noc_adjustments) : '') + '</small></div></div></div>')); });
    return parts.join('');
  },
  financingPayload(rows) {
    const out = [], seen = new Set();
    (rows || []).filter(r => r.stopType !== 'TAREA').forEach(r => FinancingPlans.active(rowKey(r)).forEach(p => { if (seen.has(p.id)) return; seen.add(p.id);
      out.push({ plan_id: p.id, comp: p.comp, client_key: p.client_key, client_name: p.client_name || r.cliente, classification: 'FINANCIACION_PROPIA_VIGENTE', frequency: p.frequency, parts: p.parts,
        resolver_version: window.OKFinancing.RESOLVER_VERSION, import_id: p.last_import_id }); }));
    return out;
  },
  nocItem(r, n) { return { comp: n.comp, cuit: n.cuit || (r.calc && r.calc.cuit) || '', issued_date: n.d || '', original_amount: n.orig, available_amount: n.amt }; },
  rowOrders(r) { return [r.mainOrder, r.shipOrder].concat(r.orders || []).filter(Boolean).map(String).filter((v, i, a) => a.indexOf(v) === i); },
  // RC3: antecedente en una hoja CANCELADA (mismo pedido): en revisión → solo informa; MANTENIDA por Administración → se puede considerar sin un segundo consumo
  priorHtml(x, d) {
    const orders = this.rowOrders(x.r), pr = (d.prior || []).filter(p => !(p.order_numbers || []).length || p.order_numbers.some(o => orders.includes(String(o))));
    return pr.map(p => p.resolution === 'KEEP' && (!p.reassigned_sheet_key || p.reassigned_sheet_key === RouteStore.sheetId)
      ? '<div class="nocprior keep" data-app="' + p.app_id + '" data-amt="' + p.amount + '"><b>APLICACIÓN MANTENIDA</b> de la hoja ' + esc(p.route_number || '') + ' (cancelada): ' + ars(p.amount) + ' ya aplicados a este pedido.' +
        (p.reassigned_sheet_key === RouteStore.sheetId ? ' <span class="nocres">Considerada en esta hoja (sin nuevo consumo).</span>' : ' <button type="button" class="btn soft" data-nocreuse>CONSIDERAR EN ESTA HOJA (sin nuevo consumo)</button>') + '</div>'
      : '<div class="nocprior"><b>ANTECEDENTE</b>: aplicada ' + ars(p.amount) + ' en la hoja ' + esc(p.route_number || '') + ' (cancelada) · ' + esc(nocReconLabel(p.state)) + '.</div>').join('');
  },
  async nocDetect(rows) {
    const b = window.OKD_BRIDGE && window.OKD_BRIDGE.noc; if (!b || !b.detect) return {};
    const items = []; rows.forEach(r => this.nocList(r).forEach(n => items.push(this.nocItem(r, n))));
    if (!items.length) return {};
    try { const res = await b.detect(RouteStore.sheetId, items); const map = {}; res.forEach(x => { map[x.comp] = x; }); return map; } catch (e) { return { __error: e.message }; }
  },
  nocHtml(rows, info) {
    const items = rows.map((r, i) => ({ r, i, list: this.nocList(r) })).filter(x => x.list.length);
    if (!items.length || !(window.OKD_BRIDGE && window.OKD_BRIDGE.noc)) return '';
    info = info || {};
    const row = (x, n) => {
      const d = info[n.comp] || {}, head = '<span><b>' + esc(x.r.cliente) + '</b> · ' + esc(n.comp) + ' · ' + esc(isoToDMY(n.d) || 's/f') + '</span>';
      const attrs = ' data-i="' + x.i + '" data-comp="' + esc(n.comp) + '" data-date="' + esc(n.d || '') + '" data-amt="' + n.amt + '" data-orig="' + (n.orig != null ? n.orig : '') + '" data-cuit="' + esc(n.cuit || (x.r.calc && x.r.calc.cuit) || '') + '"';
      if (info.__error || d.error) return '<div class="nocrow blocked"' + attrs + '>' + head + '<span class="nocres">No se pudo verificar la NOC en el servidor (' + esc(info.__error || d.error) + '): no se ofrece.</span></div>';
      const prior = this.priorHtml(x, d);
      if (['CANCELLED_ROUTE_REVIEW', 'CIANBOX_DIFFERENCE'].includes(d.reconciliation_status)) return '<div class="nocrow blocked"' + attrs + '>' + head + '<span class="nocres"><b>NOTA DE CRÉDITO EN REVISIÓN ADMINISTRATIVA</b> · ' + esc(nocReconLabel(d.reconciliation_status)) + ' · no se puede aplicar hasta que Administración la resuelva</span>' + prior + '</div>';
      if (prior && /data-nocreuse|Considerada/.test(prior)) return '<div class="nocrow"' + attrs + '>' + head + prior + '</div>';
      if (d.status === 'UTILIZADA' || (d.available <= 0.004 && !d.mine)) return '<div class="nocrow blocked"' + attrs + '>' + head + '<span class="nocres"><b>NOTA DE CRÉDITO YA UTILIZADA</b> · original ' + ars(d.original) + ' · consumido ' + ars(d.consumed) +
        (d.used_at ? ' · ' + esc(new Date(d.used_at).toLocaleDateString('es-AR')) : '') + (d.used_destination ? ' · ' + esc(d.used_destination === 'FINANCIACION_PROPIA' ? 'financiación propia' : 'pedido') : '') + (d.used_reference ? ' · ' + esc(d.used_reference) : '') + '</span></div>';
      if (d.reserved_elsewhere) return '<div class="nocrow blocked"' + attrs + '>' + head + '<span class="nocres"><b>NOTA DE CRÉDITO RESERVADA EN OTRO BORRADOR</b>' + (d.reserved_by ? ' · ' + esc(d.reserved_by) : '') + '</span></div>';
      if (['IGNORADA', 'RECHAZADA'].includes(d.status)) return '<div class="nocrow blocked"' + attrs + '>' + head + '<span class="nocres"><b>NOC ' + d.status + '</b> por Administración</span></div>';
      if (d.mine > 0) return '<div class="nocrow"' + attrs + '>' + head + '<span class="nocres">APLICADA ' + ars(d.mine) + ' en esta hoja</span></div>';
      const plans = FinancingPlans.blocked(rowKey(x.r)) ? [] : FinancingPlans.active(rowKey(x.r));
      const plan = plans.length === 1 ? plans[0] : null;
      const sel = plans.length > 1 ? '<select class="ed" data-planpick><option value="">Elegí el plan de financiación…</option>' + plans.map(p => '<option value="' + p.id + '">' + esc(p.comp_label || p.comp) + ' · ' + FinancingPlans.freqLabel(p.frequency) + ' · saldo ' + ars(p.operational_pending) + (p.next_due ? ' · próxima ' + esc(isoToDMY(p.next_due)) : '') + '</option>').join('') + '</select>' : '';
      return '<div class="nocrow"' + attrs + (plan ? ' data-plan="' + plan.id + '"' : '') + '>' + head + '<span>disponible ' + ars(d.available) + (d.status === 'PARCIALMENTE_UTILIZADA' ? ' (remanente de ' + ars(d.original) + ')' : '') + '</span>' +
        '<span class="nocq">¿Dónde querés aplicar esta Nota de Crédito?</span><input class="ed" data-nocamt inputmode="decimal" value="' + d.available + '">' +
        (plans.length ? sel + '<button type="button" class="btn soft" data-nocfin>APLICAR A FINANCIACIÓN PROPIA</button>' : (FinancingPlans.blocked(rowKey(x.r)) ? '<span class="nocres">Financiación sin sincronizar: REVISAR</span>' : '')) +
        '<button type="button" class="btn soft" data-nocok>APLICAR AL PEDIDO ACTUAL</button><button type="button" class="btn ghost" data-nocno>NO APLICAR</button><span class="nocres" data-nocres></span></div>';
    };
    return '<div class="nocbox" id="pubNoc"><b>NOTAS DE CRÉDITO (NOC) · se aplican solo si las aceptás</b><p class="rp-note">Por defecto el piso del cobro es el Saldo CC. Si aceptás una NOC, su importe reduce ese piso y el cobro. Si no la aceptás, el piso sigue siendo el Saldo CC. Cada NOC se usa una sola vez: se ofrece solo el remanente real según el servidor.</p>' +
      items.map(x => x.list.map(n => row(x, n)).join('')).join('') + '</div>';
  },
  bindNoc(m, rows) {
    const b = window.OKD_BRIDGE && window.OKD_BRIDGE.noc; if (!b) return;
    m.querySelectorAll('[data-nocreuse]').forEach(btn => btn.onclick = async () => {   // reasociación operativa: NO es un segundo consumo
      const box = btn.closest('.nocprior'), el = btn.closest('.nocrow'), r = rows[+el.dataset.i]; btn.disabled = true;
      try {
        const res = await b.reassociate(box.dataset.app, RouteStore.sheetId);
        r.nocApplied = Math.round(((r.nocApplied || 0) + res.amount) * 100) / 100; (r.nocList = r.nocList || []).push({ fingerprint: res.fingerprint, comp: el.dataset.comp, applied: res.amount, reassociated: true });
        btn.replaceWith(Object.assign(document.createElement('span'), { className: 'nocres', textContent: 'Considerada en esta hoja (sin nuevo consumo): ' + ars(res.amount) }));
        RouteStore.log({ tipo: 'NOC mantenida considerada en la hoja', comp: el.dataset.comp, importe: res.amount });
      } catch (e) { btn.disabled = false; toast(String(e.message || e).replace(/^[A-Z_]+:\s*/, '')); }
    });
    m.querySelectorAll('.nocrow').forEach(el => { if (!el.querySelector('[data-nocok]')) return; // NOC ya utilizada / reservada / bloqueada: sin acciones
      const r = rows[+el.dataset.i], out = el.querySelector('[data-nocres]');
      const done = () => el.querySelectorAll('[data-nocok],[data-nocfin],[data-nocno],[data-planpick]').forEach(x => { x.disabled = true; });
      el.querySelector('[data-nocno]').onclick = () => { out.textContent = 'NO SE APLICA'; done(); };
      const fin = el.querySelector('[data-nocfin]');
      if (fin) fin.onclick = async () => {
        const amount = Number(String(el.querySelector('[data-nocamt]').value).replace(/\./g, '').replace(',', '.'));
        if (!(amount > 0)) { out.textContent = 'Importe inválido.'; return; }
        const pick = el.querySelector('[data-planpick]'); const planId = pick ? pick.value : el.dataset.plan;
        if (!planId) { out.textContent = 'Elegí a qué plan de financiación aplicar la NOC (hay más de uno activo).'; return; }   // sin prioridad inventada
        if (FinancingPlans.blocked(rowKey(r))) { out.textContent = 'Financiación sin sincronizar: REVISAR.'; return; }
        el.dataset.plan = planId;
        done();
        try {
          // Solo baja el saldo operativo del plan; el pedido actual no cambia y no se incorpora al plan
          const res = await b.applyFinancing({ plan_id: el.dataset.plan, cuit: el.dataset.cuit, comp: el.dataset.comp, issued_date: el.dataset.date, original_amount: el.dataset.orig ? Number(el.dataset.orig) : null,
            available_amount: Number(el.dataset.amt), amount, op_id: 'nocfin-' + RouteStore.sheetId + '-' + el.dataset.comp, accept: true });
          if (res.ok === false) { out.innerHTML = '<b>' + esc(res.message) + '</b>'; el.classList.add('blocked'); return; }
          out.textContent = 'APLICADA A FINANCIACIÓN PROPIA ' + ars(res.applied) + ' · saldo del plan ' + ars(res.plan_operational_pending) + ' · remanente NOC ' + ars(res.remaining);
          FinancingPlans.store([Object.assign({}, (FinancingPlans.byClient.get(rowKey(r)) || []).find(p => p.id === el.dataset.plan) || {}, { id: el.dataset.plan, client_key: rowKey(r), operational_pending: res.plan_operational_pending, noc_adjustments: res.plan_noc_adjustments, status: res.plan_status })]);
          const box = m.querySelector('.finbox[data-plan="' + el.dataset.plan + '"] [data-finsaldo]'); if (box) box.textContent = ars(res.plan_operational_pending);
          RouteStore.log({ tipo: 'NOC aplicada a financiación propia', comp: el.dataset.comp, importe: res.applied });
        } catch (e) {   // error transitorio (red/servidor): se rehabilitan controles conservando plan e importe
          out.textContent = 'No se pudo aplicar: ' + String(e.message || e).replace(/^[A-Z_]+:\s*/, '') + '. Podés reintentar.';
          el.querySelectorAll('[data-nocok],[data-nocfin],[data-nocno],[data-planpick]').forEach(x => { x.disabled = false; });
        }
      };
      el.querySelector('[data-nocok]').onclick = async ev => {
        const amount = Number(String(el.querySelector('[data-nocamt]').value).replace(/\./g, '').replace(',', '.'));
        if (!(amount > 0)) { out.textContent = 'Importe inválido.'; return; }
        const cc = FinancialIndex.findCC ? FinancialIndex.findCC(r.calc && r.calc.cuit, r.cliente) : null;
        ev.target.disabled = true;
        try {
          // Identidad de la NOC: tipo+letra+PV+número (del comprobante) + CUIT + fecha de emisión + importe original (columna "Monto original")
          const res = await b.apply({ sheet_key: RouteStore.sheetId, cuit: el.dataset.cuit, comp: el.dataset.comp, issued_date: el.dataset.date, original_amount: el.dataset.orig ? Number(el.dataset.orig) : null,
            available_amount: Number(el.dataset.amt), amount, order_numbers: this.rowOrders(r), order_amount: (r.monto || 0) - (r.nocApplied || 0), cc_saldo: cc && cc.s != null ? cc.s : 0, op_id: 'noc-' + RouteStore.sheetId + '-' + el.dataset.comp, accept: true });
          if (res.ok === false) { out.innerHTML = '<b>' + esc(res.message) + '</b>' + (res.code === 'NOC_CONSUMED' ? ' · consumido ' + ars(res.consumed) : ''); el.classList.add('blocked'); el.querySelector('[data-nocamt]').remove(); return; } // otra sesión la usó/reservó: estado actualizado
          if (!res.repeated) { r.nocApplied = Math.round(((r.nocApplied || 0) + res.applied) * 100) / 100; (r.nocList = r.nocList || []).push({ fingerprint: res.fingerprint, comp: el.dataset.comp, applied: res.applied }); }
          out.textContent = 'APLICADA ' + ars(res.applied) + (res.floor_after != null ? ' · piso ' + ars(res.floor_before) + ' → ' + ars(res.floor_after) : '') + ' · remanente NOC ' + ars(res.remaining); RouteStore.log({ tipo: 'NOC aplicada', comp: el.dataset.comp, importe: res.applied });
        } catch (e) { out.textContent = String(e.message || e).replace(/^NOC_[A-Z_]+:\s*/, ''); ev.target.disabled = false; }
      };
    });
  },
  // Preparación antes de publicar: LISTO / LISTO CON ADVERTENCIAS / REVISAR
  readiness(rows, carrier, resp, bad, vehicles, external) {
    const items = [], add = (lvl, t) => items.push([lvl, t]);
    if (window.OKD_CFG_STATE && window.OKD_CFG_STATE !== 'OK') add('err', 'CONFIGURACIÓN · SIN CONEXIÓN / REVISAR: la hoja se calculó con la configuración local de contingencia');
    if (this.tplErr) add('err', 'No se pudo verificar la plantilla de columnas de ' + this.tplErr.carrier + ' (' + this.tplErr.msg + '). Usá REINTENTAR.');
    const deliveryRows = rows.filter(r => r.stopType !== 'TAREA');
    const finBlocked = deliveryRows.filter(r => FinancingPlans.blocked(rowKey(r)));
    if (finBlocked.length) add('err', 'FINANCIACIÓN PROPIA · REVISAR: la sincronización falló para ' + finBlocked.length + ' entrega(s) con financiación (reintentá antes de publicar)');
    if (carrier && carrier.kind === 'INTERNO') add(vehicles && vehicles.length ? 'ok' : 'err', vehicles && vehicles.length ? 'Ruta interna: vehículo asignado (obligatorio)' : 'Ruta interna sin vehículo activo: dalo de alta en CONFIGURACIÓN → VEHÍCULOS');
    add(carrier ? 'ok' : 'err', carrier ? 'Transportista: ' + carrier.name : 'Transportista sin definir o hay más de uno');
    if (external) add('ok', 'Despacho tercerizado: no requiere responsable de app');
    else add(resp.length ? 'ok' : 'err', resp.length ? 'Responsable compatible disponible' : 'Sin responsable compatible');
    add(rows.length ? 'ok' : 'err', rows.length + ' entrega(s)');
    if (bad.length) add('err', bad.length + ' pedido(s) con montos/documentos, financiación o NOC por revisar');
    const noAddr = rows.filter(r => r.stopType === 'TAREA' ? !String(r.domicilio || '').trim() : (!String(r.domicilio || '').trim() || !String(r.localidad || '').trim())).length; if (noAddr) add('warn', noAddr + ' parada(s) sin domicilio completo');
    const noBul = deliveryRows.filter(r => !(parseInt(r.bultos, 10) > 0)).length; if (noBul) add('warn', noBul + ' entrega(s) con 0 bultos');
    const warns = deliveryRows.filter(r => { const st = baseStatus(r); return !st.blocking && st.issues.some(i => i.level === 'warn'); }).length; if (warns) add('warn', warns + ' entrega(s) con advertencias');
    const noMail = deliveryRows.filter(r => { const cc = FinancialIndex.findCC ? FinancialIndex.findCC(r.calc && r.calc.cuit, r.cliente) : null; return !(r.email || (cc && cc.email)); }).length;
    if (noMail) add('warn', noMail + ' cliente(s) sin email (no reciben avisos)');
    const level = items.some(i => i[0] === 'err') ? 'REVISAR' : items.some(i => i[0] === 'warn') ? 'LISTO CON ADVERTENCIAS' : 'LISTO';
    return { level: level === 'REVISAR' ? 'REVISAR' : level === 'LISTO' ? 'LISTO' : 'WARN', label: level, items };
  },
  problems() {
    return this.rows().filter(r => r.stopType !== 'TAREA').filter(r => { const st = baseStatus(r); return r.monto == null || (st.blocking && !(r.calc && r.calc.shipProv && st.issues.every(i => i.level !== 'error' && (i.level !== 'warn' || i.code === 'ENVÍO A CONFIRMAR')))); });
  },
  async payload(carrier, responsable) {
    return { sheet_key: RouteStore.sheetId, carrier_id: carrier.id, responsable_id: responsable,
      stops: this.rows().map(r => { const p = Money.parts(r), prov = r.calc && r.calc.shipProv;
        const cc = FinancialIndex.findCC ? FinancialIndex.findCC(r.calc && r.calc.cuit, r.cliente) : null, cristian = ['CT-ESTE', 'CT-ALR'].includes(carrier.id);
        return { client_name: r.cliente, client_key: r.stopType === 'TAREA' ? ('TASK-' + r.id) : ((r.calc && r.calc.cuit) || Normalizer.name(r.cliente)), zone: this.zone(r, carrier), order_numbers: [r.mainOrder, r.shipOrder].filter(Boolean).map(String),
          // Cristian cobra el monto de la hoja: entrega + cobranza con importe esperado (el chofer no lo modifica)
          task: cristian && (r.monto || 0) > 0 ? 'AMBAS' : 'ENTREGA', expected_amount: cristian && (r.monto || 0) > 0 ? r.monto : null,
          stop_type: r.stopType || 'PEDIDO', instructions: r.taskInstructions || null, contact_name: r.taskContact || null, contact_phone: r.taskPhone || null,
          customer_email: r.stopType === 'TAREA' ? null : (r.email || (cc && cc.email) || null),
          merchandise_amount: r.stopType === 'TAREA' ? 0 : (p.main || 0), shipping_fee: r.stopType === 'TAREA' ? 0 : (p.ship || 0), ship_fee_status: prov ? 'PROVISIONAL' : 'SALDO', ship_order: r.shipOrder || null, address: r.domicilio || '', ready: true }; }) };
  },
  async open() {
    const b = this.bridge(); if (!b) return;
    if (RouteStore.published) { toast('Esta hoja ya está publicada (' + RouteStore.published.number + ').'); return; }
    // Configuración vigente del servidor: si estaba en contingencia, esto la recupera, aplica y recalcula antes de revisar
    if (window.OKD_SYNC_CONFIG) await window.OKD_SYNC_CONFIG();
    if (window.OKD_CFG_STATE && window.OKD_CFG_STATE !== 'OK') { toast('CONFIGURACIÓN · SIN CONEXIÓN / REVISAR: no se puede publicar hasta recuperar las reglas del servidor.', 6000); return; }
    const rows = this.rows(); if (!rows.length) { toast('La hoja no tiene pedidos para publicar.'); return; }
    const bad = this.problems();
    const carriers = await b.carriers();
    const names = [...new Set(rows.map(r => r.transportista).filter(Boolean))];
    const carrier = names.length === 1 ? this.carrierMatch(carriers, names[0]) : null;
    const external = !!(carrier && carrier.kind === 'EXTERNO' && carrier.report_group !== 'CRISTIAN_TORRES');
    const m = document.createElement('div'); m.className = 'modal open'; m.id = 'publishModal';
    let resp = [];
    if (carrier && !external) { try { resp = await b.responsables(carrier.id); } catch (e) { resp = []; } }
    const vehicles = carrier && carrier.kind === 'INTERNO' && b.vehicles ? (await b.vehicles().catch(() => [])).filter(v => v.active) : [];
    // Plantilla: "sin plantilla" (respuesta válida → predeterminada) ≠ error del servidor (→ REVISAR, no se publica)
    let tpl = null, tplErr = null;
    if (carrier && b.template) { try { tpl = await b.template(carrier.id); } catch (e) { tplErr = e.message || String(e); } }
    this.tplErr = tplErr ? { carrier: carrier.name, msg: tplErr } : null;
    await FinancingPlans.forClients(rows.filter(r => r.stopType !== 'TAREA').map(rowKey)); // espera la sincronización de financiación pendiente
    const ready = this.readiness(rows, carrier, resp, bad, vehicles, external);
    const nocInfo = await this.nocDetect(rows); // estado REAL de cada NOC en el servidor (nunca solo el Excel)
    const blockMsg = !carrier ? (names.length > 1 ? 'La hoja tiene pedidos de varios transportistas (' + names.join(', ') + '). Prepará una hoja por transportista.' : 'El transportista "' + (names[0] || '') + '" no está dado de alta.')
      : (!external && !resp.length) ? 'No hay usuarios activos compatibles con ' + carrier.name + '.'
      : bad.length ? 'Hay ' + bad.length + ' pedido(s) con revisión pendiente o sin monto: ' + bad.map(r => r.mainOrder || r.shipOrder).join(', ') + '.' : '';
    const title = external ? 'DESPACHAR E IMPRIMIR' : 'PUBLICAR HOJA';
    m.innerHTML = '<div class="dialog" role="dialog" aria-modal="true"><header><b>' + title + '</b></header><div class="body">' +
      '<p>Transportista: <b>' + esc(carrier ? carrier.name : (names.join(', ') || '—')) + '</b> · ' + rows.length + ' entregas</p>' +
      (external ? '<p>Al confirmar, la hoja quedará registrada como <b>despachada al transporte tercerizado</b>, contará en Informes → Otros transportistas, se guardará el PDF y se abrirá la impresión.</p>' : '') +
      (!external && resp.length ? '<label>Responsable <select class="ed" id="pubResp">' + resp.map(u => '<option value="' + u.id + '">' + esc(u.full_name) + '</option>').join('') + '</select></label>' : '') +
      (carrier && carrier.kind === 'INTERNO' && vehicles.length ? '<label>Vehículo (obligatorio) <select class="ed" id="pubVeh">' + vehicles.map(v => '<option value="' + v.id + '">' + esc(v.name + ' · ' + v.plate) + '</option>').join('') + '</select></label>' : '') +
      (blockMsg ? '<p class="shiperr" id="pubBlock">' + esc(blockMsg) + '</p>' : '') +
      '<div class="ready ' + ready.level + '" id="pubReady"><b>' + ready.label + '</b><ul>' + ready.items.map(i => '<li class="' + i[0] + '">' + esc(i[1]) + '</li>').join('') + '</ul></div>' +
      '<div class="bulwrap"><table class="bultab"><thead><tr><th>PARADA</th><th>BULTOS</th></tr></thead><tbody>' + rows.map((r, i) => '<tr><td>' + esc(r.cliente) + ' <small>' + esc(r.mainOrder || '') + '</small></td><td><input class="ed" data-bul="' + i + '" inputmode="numeric" value="' + (parseInt(r.bultos, 10) || 0) + '"></td></tr>').join('') +
      '</tbody></table><p class="sheetsum" id="pubSum">' + sheetSummary(rows) + '</p></div>' +
      this.finHtml(rows) + this.nocHtml(rows, nocInfo) +
      (tpl ? '<p class="rp-note">Plantilla de hoja: ' + (tpl.version ? 'v' + tpl.version : 'predeterminada') + '</p>' : '') +
      '<p class="shiperr" id="pubErr" hidden></p></div>' +
      '<footer><button class="btn ghost" type="button" id="pubCancel">Cancelar</button>' + (this.tplErr || rows.some(r => FinancingPlans.blocked(rowKey(r))) ? '<button class="btn soft" type="button" id="pubRetry">REINTENTAR</button>' : '') +
      '<button class="btn go" type="button" id="pubGo"' + (blockMsg ? ' disabled' : '') + '>' + title + '</button></footer></div>';
    document.body.appendChild(m);
    m.querySelector('#pubCancel').onclick = () => m.remove();
    const bulVals = () => [...m.querySelectorAll('[data-bul]')].map(x => x.value.trim());
    m.querySelectorAll('[data-bul]').forEach(inp => inp.oninput = () => { const v = bulVals(); m.querySelector('#pubSum').textContent = sheetSummary(rows.map((r, i) => ({ sale: true, bultos: v[i] }))); });
    const vs = m.querySelector('#pubVeh'), rs = m.querySelector('#pubResp');
    const habitual = () => { if (!vs || !rs) return; const v = vehicles.find(x => x.habitual_driver_id === rs.value); if (v) vs.value = v.id; };
    if (rs) rs.addEventListener('change', habitual); habitual();
    if (ready.level === 'REVISAR') m.querySelector('#pubGo').disabled = true;
    this.bindNoc(m, rows);
    const rt = m.querySelector('#pubRetry');
    if (rt) rt.onclick = async () => { rt.disabled = true; await FinancingPlans.retry(); m.remove(); this.open(); }; // vuelve a verificar plantilla y financiación
    m.querySelector('#pubGo').onclick = async ev => {
      ev.target.disabled = true;
      try {
        const bv = bulVals(); if (bv.some(v => !/^\d+$/.test(v))) { const er = m.querySelector('#pubErr'); er.textContent = 'Los bultos deben ser números enteros mayores o iguales a 0.'; er.hidden = false; ev.target.disabled = false; return; }
        rows.forEach((r, i) => { r.bultos = parseInt(bv[i], 10); });
        const keep = rows.map(r => ({ r, monto: r.monto, obs: r.obsPago }));
        rows.forEach(r => { if (r.nocApplied > 0 && r.monto != null) { r.monto = Math.round((r.monto - r.nocApplied) * 100) / 100; r.obsPago = [r.obsPago, (r.nocList || []).map(x => 'NOC ' + x.comp + ' aplicada ' + ars(x.applied)).join(' · ')].filter(Boolean).join(' · '); } });
        try {
        const respSel = m.querySelector('#pubResp');
        const pl = await this.payload(carrier, respSel ? respSel.value : null); const veh = m.querySelector('#pubVeh'); if (veh && veh.value) pl.vehicle_id = veh.value;
        pl.financing = this.financingPayload(rows); // snapshot de financiación propia (plan real) al publicar
        pl.stops.forEach((st, i) => { if (rows[i].nocApplied > 0) { st.noc = rows[i].nocList; st.merchandise_amount = Math.max(0, Math.round(((st.merchandise_amount || 0) - rows[i].nocApplied) * 100) / 100); } });
        pl.stops.forEach((st, i) => { st.bultos = rows[i].bultos; });
        const cols = tpl ? tpl.columns : null;
        pl.template = tpl ? { template_id: tpl.id, version: tpl.version, carrier_id: carrier.id, columns: cols } : null;
        pl.rules_version = window.OKD_RULES_VERSION || null; pl.routing_rules_version = window.OKD_ROUTING_VERSION || null;
        pl.summary = sheetSummary(rows);
        // El PDF sale SIEMPRE de este snapshot publicado (columnas de la plantilla vigente al publicar)
        const ec = Config.get().exportCols.slice(); Config.get().exportCols = ec.map(() => true);
        let model; try { model = ExportModel.build(); } finally { Config.get().exportCols = ec; }
        // Cada salida según su flag de la plantilla (snapshot completo de la plantilla en pl.template)
        const ctxT = { responsable: (resp.find(u => u.id === pl.responsable_id) || {}).full_name || '', summary: pl.summary }, base = JSON.stringify(model);
        const out = flag => { const mm = JSON.parse(base); if (cols) ExportModel.applyTemplate(mm, cols, ctxT, flag); return mm; };
        pl.pdf_model = out('pdf'); pl.xlsx_model = out('excel'); pl.screen_model = out('screen');
        var plOut = pl;
        } finally { keep.forEach(k => { k.r.monto = k.monto; k.r.obsPago = k.obs; }); }
        const pl = plOut;
        if (external) {
          const r = await b.dispatchExternal(pl);
          RouteStore.published = { id: r.id, number: r.number, at: r.dispatched_at || r.completed_at || r.published_at, carrier: carrier.name, responsable: '', mode: 'EXTERNAL' };
          RouteStore.log({ tipo: 'hoja despachada a transporte tercerizado', numero: r.number, transportista: carrier.name, version: r.version || 1 }); await RouteStore.flush();
          m.remove(); toast('Hoja ' + r.number + ' despachada a ' + carrier.name + ' · registrada en informes.'); SheetTabs.render();
          await this.afterPublish(r, pl.pdf_model, false); await this.render();
          const pb = document.getElementById('btnPrint'); if (pb) pb.click();
        } else {
          const r = await b.publish(pl);
          RouteStore.published = { id: r.id, number: r.number, at: r.published_at, carrier: carrier.name, responsable: (resp.find(u => u.id === r.responsable_id) || {}).full_name || '', mode: 'APP' };
          RouteStore.log({ tipo: 'hoja publicada', numero: r.number }); await RouteStore.flush();
          m.remove(); toast('Hoja ' + r.number + ' publicada · disponible en tiempo real para ' + RouteStore.published.responsable); SheetTabs.render();
          await this.afterPublish(r, pl.pdf_model, true); this.render();
        }
      } catch (e) { const er = m.querySelector('#pubErr'); er.textContent = e.message; er.hidden = false; ev.target.disabled = false; }
    };
  },
  // ===== PDF automático al publicar (RC1.2): se guarda en Storage privado; la descarga es aparte y nunca revierte la publicación =====
  async afterPublish(r, model, allowDownload = true) {
    const b = this.bridge(), pdf = b.pdf; if (!pdf) return;
    const cfg = await pdf.settings().catch(() => ({ pdf_auto_generate: true, pdf_auto_download: true }));
    if (!cfg.pdf_auto_generate) { RouteStore.published.pdf = { status: 'NO_GENERADO', version: r.version || 1 }; await RouteStore.flush(); return; }
    await this.makePdf(r.id, r.number, r.version || 1, model);
    const p = RouteStore.published.pdf;
    if (p.status === 'OK' && allowDownload && cfg.pdf_auto_download) p.downloaded = this.tryDownload(p.bytes, p.file_name);
    delete p.bytes; await RouteStore.flush();
  },
  async makePdf(id, number, version, model) {
    const pdf = this.bridge().pdf, file = 'Hoja_' + number + '_v' + version + '.pdf';
    try {
      const bytes = PdfExporter.bytesFromModel(model);
      await pdf.save(id, version, number, bytes);
      RouteStore.published.pdf = { status: 'OK', version, file_name: file, bytes };
    } catch (e) {
      await pdf.error(id, version, String(e.message || e)).catch(() => null);
      RouteStore.published.pdf = { status: 'PDF_ERROR', version, file_name: file, error: String(e.message || e) };
    }
  },
  tryDownload(bytes, name) {
    try { if (window.OKD_DL_FAIL) throw new Error('Descarga bloqueada por el navegador'); ExportModel.download(new Blob([bytes], { type: 'application/pdf' }), name); return true; }
    catch (e) { return false; }
  },
  async retryPdf() {
    const pub = RouteStore.published, snap = await this.bridge().pdf.snapshot(pub.id); // siempre desde lo publicado
    await this.makePdf(pub.id, snap.number, pub.pdf.version, snap.pdf_model); delete RouteStore.published.pdf.bytes; await RouteStore.flush(); this.render();
  },
  async downloadPdf() {
    const pub = RouteStore.published; const blob = await this.bridge().pdf.download(pub.id, pub.pdf.version);
    ExportModel.download(blob, pub.pdf.file_name);
  },
  // PUBLICADA → NOTIFICADA → VISTA → INICIADA → FINALIZADA (en vivo)
  async render() {
    const btn = document.getElementById('btnPublish'), box = document.getElementById('pubStatus'), b = this.bridge();
    const standalonePrint = document.getElementById('btnPrint'), standalonePdf = document.getElementById('btnPdf');
    if (!btn || !box) return;
    if (b) { if (standalonePrint) standalonePrint.hidden = true; if (standalonePdf) standalonePdf.hidden = true; }
    btn.hidden = !b; if (!b) return;
    const pub = RouteStore.published;
    if (!pub) {
      const seq = ++this._renderSeq;
      btn.disabled = false; btn.textContent = 'PUBLICAR HOJA';
      try {
        const names = this.actionNames();
        const carriers = names.length ? await b.carriers() : [];
        if (seq !== this._renderSeq) return;
        const carrier = names.length === 1 ? this.carrierMatch(carriers, names[0]) : null;
        const external = !!(carrier && carrier.kind === 'EXTERNO' && carrier.report_group !== 'CRISTIAN_TORRES');
        btn.textContent = external ? 'DESPACHAR E IMPRIMIR' : 'PUBLICAR HOJA';
        btn.dataset.carrierMode = external ? 'EXTERNAL' : 'APP';
      } catch (e) {}
      box.hidden = true; return;
    }
    btn.textContent = (pub.mode === 'EXTERNAL' ? 'DESPACHADA ' : 'PUBLICADA ') + pub.number; btn.disabled = true;
    box.hidden = false;
    let st = null; try { st = await b.status(pub.id); } catch (e) { st = null; }
    const step = (k, label, at) => '<div class="pst' + (at ? ' on' : '') + '" data-st="' + k + '"><span>' + label + '</span><b>' + (at ? new Date(at).toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' }) : '—') + '</b></div>';
    box.innerHTML = '<div class="pubbar"><b>HOJA ' + esc(pub.number) + '</b> · ' + esc(pub.carrier) + ' · ' + esc(pub.responsable) + '</div><div class="psteps">' +
      '' + step('PUBLICADA', 'PUBLICADA', st ? st.published_at : pub.at) + step('NOTIFICADA', 'NOTIFICADA', st && st.notified_at) + step('VISTA', 'VISTA', st && st.viewed_at) + step('INICIADA', 'INICIADA', st && st.started_at) + step('FINALIZADA', 'FINALIZADA', st && st.completed_at) + '</div>' +
      (pub.pdf ? '<div class="pdfbar" id="pdfBar">' + (pub.pdf.status === 'OK' ? '<b>✓ HOJA PUBLICADA · ✓ PDF GENERADO</b><span>' + esc(pub.pdf.file_name) + (pub.pdf.downloaded ? ' · descargado' : '') + '</span><button class="btn soft" type="button" id="pdfDl">DESCARGAR PDF</button>'
        : pub.pdf.status === 'PDF_ERROR' ? '<b>HOJA PUBLICADA · PDF PENDIENTE</b><span>' + esc(pub.pdf.error || '') + '</span><button class="btn dark" type="button" id="pdfRetry">REINTENTAR PDF</button>'
        : '<b>✓ HOJA PUBLICADA</b><span>PDF automático desactivado</span>') + '</div>' : '');
    const dl = box.querySelector('#pdfDl'); if (dl) dl.onclick = () => this.downloadPdf().catch(e => toast(e.message));
    const rt = box.querySelector('#pdfRetry'); if (rt) rt.onclick = async () => { rt.disabled = true; await this.retryPdf(); };
  }
};

const RouteStore = {
  rows: [], selected: new Set(), data: { pedidos: null, sc: null, cc: null }, sheetDate: '', audit: [], opNotesInExcel: false, showCash: true, showCheques: true, showTransfers: true, oldDecisions: {},
  save: null,
  init() {
    this.flush = () => { SheetTabs.touch(); return DB.set('sheet:' + this.sheetId, { rows: this.rows, selected: Array.from(this.selected), sheetDate: this.sheetDate, audit: this.audit.slice(-2000), showCash: this.showCash, showCheques: this.showCheques, showTransfers: this.showTransfers, oldDecisions: this.oldDecisions, sheetId: this.sheetId, published: this.published || null }); };
    this.save = debounce(this.flush, 350);
    // guardar también al cerrar o cambiar de pestaña
    window.addEventListener('pagehide', () => this.flush());
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') this.flush(); });
  },
  // Al cargar un informe nuevo: comprobante vinculado a mano vs el que trae el informe
  reconcileInforme() {
    this.rows.forEach(row => {
      const o = OrderIndex.get(row.mainOrder); if (!o || !o.factura) return;
      if (row.compLink) {
        if (Normalizer.comp(o.factura) === Normalizer.comp(row.mainDoc)) { row.compConfirmed = true; row.compConflict = null; }
        else if (!row.compKept) row.compConflict = o.factura;
      } else if (!row.mainDoc) { row.mainDoc = o.factura; row.auto = true; if (!row.payMainManual) row.payMain = Config.payFor(o.factura); }
    });
  },
  // Envío sin pedido principal claro: fila aparte, fuera de la hoja hasta que el operador lo asocie
  makePendingShip(ship, candidates) {
    const row = this.buildFromResolution({ entered: ship.id, main: null, ship, mainRef: '', flags: [], notes: [] });
    Object.assign(row, { shipPending: true, auto: false, sale: false, monto: null, calc: null, shipCandidates: candidates.slice() });
    row.linkFlags = [{ level: 'warn', code: 'ENVÍO POR ASOCIAR', text: 'El envío ' + ship.id + ' no menciona pedido en Observaciones y puede corresponder a ' + candidates.join(', ') + '. Elegí a qué pedido pertenece.' }];
    return row;
  },
  // Suma un pedido de envío a una entrega de mercadería
  attachShip(target, ship, how) {
    Object.assign(target, { hasShip: true, shipOrder: ship.id, shipDoc: ship.factura, shipCost: r2(ship.total), shipCostOrig: r2(ship.total), shipCostManual: false, awaitShip: null });
    if (!target.payShipManual) target.payShip = ship.factura ? Config.payFor(ship.factura) : Config.get().pay.NDP;
    target.shipGroup = ShippingMatcher.shipGroup(ship, target.transportista);
    target.linkFlags = (target.linkFlags || []).filter(f => f.code !== 'ENVÍO NO ENCONTRADO' && f.code !== 'ENVÍO POR ASOCIAR');
    target.linkNotes = (target.linkNotes || []).filter(n => !/POR ASOCIAR/.test(n.text)).concat([{ level: 'ship', text: how }]);
    if (target.src) target.src.obsShip = ship.obs;
    this.checkShipCost(target);
  },
  // Valida el costo de envío contra la configuración vigente
  checkShipCost(row) {
    row.linkFlags = (row.linkFlags || []).filter(f => !f.shipCost);
    if (!row.hasShip || row.shipCost == null || row.shipCostManual) return; // un costo escrito por el operador no se marca
    const grp = row.shipGroup || (/ESTE/i.test(row.transportista || '') ? 'ESTE' : 'ALREDEDORES');
    const allowed = Config.get().shipCosts[grp] || [];
    if (!allowed.some(a => Math.abs(a - row.shipCost) < 0.5))
      row.linkFlags.push({ level: 'warn', code: 'REVISAR', shipCost: true, text: 'El costo de envío ' + ars(row.shipCost) + ' no coincide con los configurados para ' + (grp === 'ESTE' ? 'Zona Este' : 'Alrededores') + ' (' + allowed.map(ars).join(' / ') + ').' });
  },
  // Aplica la configuración guardada a las filas de la hoja (sin pisar lo que el operador cambió a mano)
  applyConfig() {
    let changed = 0;
    this.rows.forEach(row => {
      const before = JSON.stringify([row.payMain, row.payShip, row.transportista, row.linkFlags]);
      if (!row.payMainManual && row.mainDoc) row.payMain = Config.payFor(row.mainDoc);
      if (row.hasShip && !row.payShipManual) row.payShip = row.shipDoc ? Config.payFor(row.shipDoc) : Config.get().pay.NDP;
      if (row.auto && row.src && row.transportista === row.carrierOrig) {
        const c = Config.carrierFor(row.src.estado, row.src.zona) || Config.carrierFor(row.src.estadoShip, row.src.zona) || '';
        if (c && c !== row.carrierOrig) { row.transportista = c; row.carrierOrig = c; }
      }
      // compatibilidad: avisos de costo de envío creados con versiones anteriores
      row.linkFlags = (row.linkFlags || []).filter(f => !(/^El costo de envío /.test(f.text || '')));
      this.checkShipCost(row);
      if (JSON.stringify([row.payMain, row.payShip, row.transportista, row.linkFlags]) !== before) changed++;
    });
    return changed;
  },
  log(entry) { entry.ts = new Date().toISOString(); entry.user = (typeof navigator !== 'undefined' && navigator.userAgent) ? 'equipo local' : ''; this.audit.push(entry); },
  find(id) { return this.rows.find(r => r.id === id); },
  usedOrders() {
    const s = new Map();
    this.rows.forEach(r => { if (r.mainOrder) s.set(String(r.mainOrder).trim(), r); if (r.hasShip && r.shipOrder) s.set(String(r.shipOrder).trim(), r); });
    return s;
  },
  newManual(order) {
    return {
      id: uid(), auto: false, manual: true, sale: true, cobradoMain: 'No', cobradoShip: 'No', reviewed: false, fecha: this.sheetDate || todayISO(),
      carrierOrig: '', opNotes: [], audit: [], domSource: null,
      mainOrder: order || '', shipOrder: '', hasShip: false, shipCost: null, mainDoc: '', shipDoc: '',
      cliente: '', domicilio: '', domicilioNote: '', localidad: '', transportista: this.selected.size === 1 ? Array.from(this.selected)[0] : '',
      payMain: 'REVISAR', payShip: 'SIMPLY', payOverride: null, obsPago: '', monto: null, montoManual: false, calc: null,
      linkFlags: [], linkNotes: [], src: { entered: order || '', manual: true }
    };
  },
  newTask(p) {
    const row = this.newManual('');
    Object.assign(row, {
      manual: false, auto: false, stopType: 'TAREA', sale: true, reviewed: true,
      cliente: p.title, domicilio: p.address, localidad: '', monto: 0, bultos: 0,
      payMain: '', payShip: '', obsPago: p.instructions || '',
      taskInstructions: p.instructions || '', taskContact: p.contact_name || '', taskPhone: p.contact_phone || '',
      transportista: this.selected.size === 1 ? Array.from(this.selected)[0] : 'TRANSPORTE INTERNO',
      carrierOrig: this.selected.size === 1 ? Array.from(this.selected)[0] : 'TRANSPORTE INTERNO',
      src: { entered: 'TAREA', manual: false, task: true }
    });
    return row;
  },
  buildFromResolution(res) {
    const main = res.main, ship = res.ship, base = main || ship;
    const carrier = (main && Config.carrierFor(main.estado, main.zona)) || (ship && Config.carrierFor(ship.estado, ship.zona)) || '';
    const row = this.newManual();
    Object.assign(row, {
      auto: true, manual: false,
      mainOrder: main ? main.id : (res.mainRef || ''),
      shipOrder: ship ? ship.id : '', hasShip: !!ship, shipCost: ship ? r2(ship.total) : null, shipCostOrig: ship ? r2(ship.total) : null,
      mainDoc: main ? main.factura : '', shipDoc: ship ? ship.factura : '',
      cliente: base.cliente, transportista: carrier, carrierOrig: carrier,
      payMain: main ? Config.payFor(main.factura) : 'REVISAR', payShip: ship ? Config.payFor(ship.factura) : Config.get().pay.NDP,
      linkFlags: res.flags.slice(), linkNotes: res.notes.slice(),
      src: {
        entered: res.entered, estado: base.estado, zona: base.zona, vendedor: base.vendedor, fechaPedido: base.fecha,
        obsMain: main ? main.obs : '', obsShip: ship ? ship.obs : '', mainTotal: main ? main.total : null,
        estadoFactura: main ? main.estadoFactura : '', lines: main ? main.lines : 0, mainFacturas: main ? main.facturas : [],
        estadoShip: ship ? ship.estado : ''
      }
    });
    if (main && main.facturas && main.facturas.length > 1) row.linkFlags.push({ level: 'warn', code: 'REVISAR', text: 'El pedido ' + main.id + ' tiene más de un comprobante: ' + main.facturas.join(', ') + '. Se tomó el primero.' });
    // Domicilio
    let dom = '', domNote = '', domSource = null;
    for (const o of [main, ship]) { if (!o) continue; dom = o.domicilio; if (dom) { domSource = { tipo: 'pedido', pedido: o.id }; break; } }
    if (!dom) for (const o of [main, ship]) { if (!o) continue; dom = Normalizer.address(o.obs) || Normalizer.address(o.obsPedido); if (dom) { domSource = { tipo: 'observaciones', pedido: o.id }; break; } }
    if (!dom) {
      const rc = FinancialIndex.findComp(row.mainDoc, row.cliente) || FinancialIndex.findComp(row.shipDoc, row.cliente);
      const cc = FinancialIndex.findCC(rc ? rc.cuit : '', row.cliente);
      if (cc && cc.dom) { dom = cc.dom; domSource = { tipo: 'cuenta corriente', cuit: cc.cuit }; }
    }
    if (!dom) {
      const a = OrderIndex.addrByClient.get(base.clientN);
      if (a) {
        const src = OrderIndex.get(a.id);
        dom = a.addr;
        domSource = { tipo: 'otro pedido', pedido: a.id, fecha: src ? src.fecha : '', domicilio: a.addr, cliente: src ? src.cliente : base.cliente };
        domNote = '⚠ DOMICILIO SUGERIDO DE OTRO PEDIDO — VERIFICAR (pedido ' + a.id + (src && src.fecha ? ' del ' + isoToDMY(src.fecha) : '') + ')';
      }
    }
    row.domicilio = dom; row.domicilioNote = domNote; row.domSource = domSource;
    // Localidad: informe primero, luego cuenta corriente
    let loc = (main && main.localidad) || (ship && ship.localidad) || '';
    if (!loc) {
      const r = FinancialIndex.findComp(row.mainDoc, row.cliente) || FinancialIndex.findComp(row.shipDoc, row.cliente);
      const cc = FinancialIndex.findCC(r ? r.cuit : '', row.cliente);
      if (cc && cc.loc) loc = cc.loc;
    }
    row.localidad = loc;
    // Validaciones de envío
    if (ship) {
      row.shipGroup = ShippingMatcher.shipGroup(ship, carrier);
      RouteStore.checkShipCost(row);
      if (row.shipDoc && Normalizer.compType(row.shipDoc) !== 'NDP') row.linkFlags.push({ level: 'warn', code: 'REVISAR', text: 'El comprobante del envío no es una NDP (' + row.shipDoc + ').' });
    } else if (main && main.shipLines > 0) {
      row.linkNotes.push({ level: 'ship', text: 'MERCADERÍA CON ENVÍO: el pedido ' + main.id + ' incluye su propio costo de envío dentro del mismo comprobante.' });
    } else if (Config.isCristian(carrier)) {
      row.linkFlags.push({ level: 'warn', code: 'ENVÍO NO ENCONTRADO', text: 'No se encontró un pedido/NDP de costo de envío que mencione el pedido ' + row.mainOrder + '.' });
    }
    const stOrig = main ? main.estado : base.estado;
    const stM = String(stOrig || '').match(/\b(COBRADO|DEVUELTO)\b/i);
    if (stM) {
      const w = stM[1].toUpperCase();
      row.linkFlags.push({ level: 'warn', code: 'ESTADO ORIGINAL DEL PEDIDO PRINCIPAL: ' + w, text: 'El pedido ' + (main ? main.id : base.id) + ' figura como "' + stOrig + '" en el informe. ' + (w === 'COBRADO' ? 'No se marca Cobrado = Sí automáticamente: confirmá manualmente si ya se cobró.' : 'Revisá si la entrega corresponde.') });
    }
    return row;
  }
};

/* ---------------- Estado de fila ---------------- */
function rowIssues(row) {
  let list = [].concat(row.linkFlags || [], (row.calc && row.calc.flags) || []);
  if (list.some(i => i.code === 'ENVÍO NO ENCONTRADO')) {
    const k = Groups.key(row), mate = RouteStore.rows.find(o => o !== row && o.hasShip && Groups.key(o) === k);
    if (mate) list = list.map(i => i.code === 'ENVÍO NO ENCONTRADO' ? { level: 'info', code: 'ENVÍO EN OTRO PEDIDO', text: 'El costo de envío de este cliente ya va en el pedido ' + mate.mainOrder + ' (envío ' + mate.shipOrder + ').' } : i);
  }
  Money.parts(row).warn.forEach(w => list.push({ level: 'warn', code: 'REVISAR', text: w }));
  if (!row.transportista) list.push({ level: 'warn', code: 'REVISAR', text: 'Falta transportista.' });
  else if (RouteStore.selected.size && !RouteStore.selected.has(row.transportista)) list.push({ level: 'info', code: 'PEDIDO DE OTRO TRANSPORTISTA', text: row.transportista + ' no está entre los transportistas seleccionados (' + Array.from(RouteStore.selected).join(', ') + ').' });
  if (row.payMain === 'REVISAR' || (row.hasShip && row.payShip === 'REVISAR')) list.push({ level: 'warn', code: 'REVISAR', text: 'Forma de pago a revisar.' });
  if (row.manual && !row.auto) list.push({ level: 'warn', code: 'REVISAR', text: 'Pedido manual: completá y verificá los datos.' });
  if (row.domicilioNote) list.push({ level: 'info', code: 'DOMICILIO SUGERIDO', text: row.domicilioNote });
  return list;
}
const STATUS_ORDER = {
  error: ['SALDO NO ENCONTRADO', 'SALDO NO INFORMADO — REVISAR', 'SIN COMPROBANTE EN INFORME', 'SIN COMPROBANTE / NO ENCONTRADO', 'SIN COMPROBANTE / NO FACTURADO', 'COMPROBANTE DIFERENTE AL VINCULADO'],
  warn: ['ENVÍO POR ASOCIAR', 'POSIBLE FINANCIACIÓN PROPIA · REVISAR', 'DIFERENCIA ENTRE COSTO DE ENVÍO Y SALDO COMPROBANTE · REVISAR', 'ENVÍO A CONFIRMAR', 'REVISAR CRÉDITO ANTIGUO', 'RELACIÓN DE ENVÍO DUDOSA', 'ENVÍO NO ENCONTRADO', 'ESTADO ORIGINAL DEL PEDIDO PRINCIPAL: COBRADO', 'ESTADO ORIGINAL DEL PEDIDO PRINCIPAL: DEVUELTO']
};
// Firma de las advertencias informativas que el operador confirmó al marcar como revisado
function reviewSig(row, issues) {
  return JSON.stringify([row.monto, issues.filter(i => ['soft', 'old', 'good'].includes(i.level)).map(i => i.code + '|' + i.text).sort()]);
}
// Estado SIN considerar la marca de revisado. Orden: ERROR → REVISAR → pendiente → advertencias → listo
function baseStatus(row) {
  const issues = rowIssues(row);
  if (row.compConflict) issues.unshift({ level: 'error', code: 'COMPROBANTE DIFERENTE AL VINCULADO', text: 'El informe trae ' + Normalizer.shortComp(row.compConflict) + ' y el pedido está vinculado a ' + Normalizer.shortComp(row.mainDoc) + '. Elegí cuál usar.' });
  const pending = row.monto == null;
  const of = lv => issues.filter(i => i.level === lv);
  const errs = of('error'), warns = of('warn');
  if (row.shipPending) return { label: 'ENVÍO POR ASOCIAR', cls: 'REVISAR', issues, blocking: true };
  if (errs.length) {
    const code = STATUS_ORDER.error.find(c => errs.some(i => i.code === c)) || 'REVISAR';
    return { label: code, cls: 'ERR', issues, blocking: true };
  }
  if (warns.length) {
    const code = STATUS_ORDER.warn.find(c => warns.some(i => i.code === c));
    return { label: code ? code.replace('ESTADO ORIGINAL DEL PEDIDO PRINCIPAL: ', 'PRINCIPAL ') : 'REVISAR', cls: 'REVISAR', issues, blocking: true };
  }
  if (pending) return { label: 'REVISAR', cls: 'REVISAR', issues, blocking: true };
  if (of('old').length) return { label: 'CRÉDITO ANTIGUO EXCLUIDO', cls: 'OLD', issues };
  if (of('soft').length) return { label: 'LISTO CON ADVERTENCIA', cls: 'YEL', issues };
  if (of('good').length) return { label: 'LISTO CON ADVERTENCIA', cls: 'YEL', favor: true, issues };
  return { label: 'LISTO', cls: 'LISTO', issues };
}
// "Revisado" solo confirma advertencias informativas ya conocidas. Nunca oculta un error ni un REVISAR,
// y se invalida solo si aparece algo nuevo (error, revisión pendiente o una advertencia distinta).
function rowStatus(row) {
  const st = baseStatus(row);
  if (row.reviewed && !row.reviewedSig) { row.reviewed = false; row.reviewedSig = null; row.reviewLegacy = true; return st; }
  if (row.reviewed) {
    if (st.blocking || (row.reviewedSig && row.reviewedSig !== reviewSig(row, st.issues))) {
      row.reviewed = false; row.reviewedSig = null;
      row.reviewLost = 'La marca de revisado se quitó porque apareció: ' + st.label + '.';
      if (typeof RouteStore !== 'undefined' && RouteStore.save) RouteStore.save();
      return st;
    }
    return { label: 'LISTO', cls: 'LISTO', reviewed: true, issues: st.issues };
  }
  return st;
}
const isReview = st => st.cls === 'ERR' || st.cls === 'REVISAR';
// Ayuda breve (2–3 líneas) para el estado de la fila
function statusHelp(row, st) {
  const codes = st.issues.map(i => i.code);
  if (row.reviewLegacy && !row.reviewed) return 'Esta marca pertenecía a una versión anterior y debe confirmarse nuevamente.';
  if (row.shipPending) return 'Este envío puede corresponder a más de un pedido. Elegí a cuál pertenece.';
  if (codes.includes('REVISAR CRÉDITO ANTIGUO')) return 'Hay un crédito de más de ' + Config.get().creditMonths + ' meses. Confirmá en el detalle si todavía está en la cuenta corriente.';
  if (codes.includes('SALDO NO INFORMADO') && st.cls === 'YEL') return 'El comprobante no informa saldo: se tomó el importe de la factura como base y se aplicó la cuenta corriente.';
  if (st.cls === 'YEL' && st.favor) return 'Se detectó un saldo a favor del cliente y se tuvo en cuenta para calcular el monto a cobrar.';
  if (st.cls === 'YEL') return 'Se cobra según la cuenta corriente del cliente. Hay una diferencia de saldo sin movimiento comprobado que no cambia el monto.';
  if (st.cls === 'GOOD') return 'Se detectó un saldo a favor del cliente y se tuvo en cuenta para calcular el monto a cobrar.';
  if (st.cls === 'OLD') return 'Un crédito de más de ' + Config.get().creditMonths + ' meses no se descuenta del cobro.';
  if (st.cls === 'LISTO') return 'Todo en orden. Tocá para ver el detalle.';
  const first = st.issues.find(i => i.level === 'error' || i.level === 'warn');
  return first ? first.text : 'Tocá para ver el detalle.';
}
// Mensajes simples debajo del estado
function statusLines(row) {
  const out = [], c = row.calc, st = rowStatus(row), codes = st.issues.map(i => i.code);
  if (row.shipPending) return ['Elegí a qué pedido pertenece'];
  if (row.reviewLegacy && !row.reviewed) out.push('REVISADO QUITADO — volver a verificar');
  else if (row.reviewLost && !row.reviewed) out.push('REVISADO QUITADO: apareció un problema nuevo');
  if (c && c.favorTotal > 0.004) {
    out.push('SE TOMA SALDO A FAVOR: ' + ars(c.favorTotal));
    out.push('Origen: ' + c.favor.map(x => Normalizer.shortComp(x.comp) + ' · ' + isoToDMY(x.d)).join(' / '));
  } else if (c && c.summary) out.push(c.summary);
  if (c && c.finGroup && c.finGroup.status !== 'NORMAL' && c.finGroup.status !== 'POSIBLE_FINANCIACION_REVISAR') out.unshift(c.finGroup.label + ' · ' + window.OKFinancing.partsText(c.finGroup));
  if (c && c.shipProv && c.shipProv.status === 'PENDING_CONFIRMATION') out.push('ENVÍO: ' + ars(c.shipProv.amount) + ' · A CONFIRMAR');
  if (codes.includes('SALDO NO INFORMADO')) out.push('SALDO NO INFORMADO — SE TOMA IMPORTE DE FACTURA');
  if (codes.includes('CRÉDITO ANTIGUO EXCLUIDO')) out.push('NO SE TOMA SALDO A FAVOR: supera los ' + Config.get().creditMonths + ' meses');
  if (codes.includes('REVISAR CRÉDITO ANTIGUO')) out.push('REVISAR CRÉDITO ANTIGUO');
  if (codes.includes('PEDIDO DE OTRO TRANSPORTISTA')) out.push('PEDIDO DE OTRO TRANSPORTISTA · ORIGINAL: ' + (row.carrierOrig || row.transportista));
  if (row.awaitShip) out.push('ENVÍO ' + row.awaitShip + ' POR ASOCIAR');
  if (row.cobradoMain === 'Sí') out.push('MERCADERÍA YA COBRADA');
  if (row.hasShip && row.cobradoMain === 'Sí' && row.cobradoShip !== 'Sí') out.push('ENVÍO PENDIENTE DE COBRO');
  return out.slice(0, 3);
}

/* ---------------- Textos de exportación ---------------- */
const Txt = {
  pedido(row) {
    if (!row.hasShip) return String(row.mainOrder || '');
    const l = ['PEDIDO PRINCIPAL: ' + (row.mainOrder || '—'), 'PEDIDO ENVÍO: ' + (row.shipOrder || '—')];
    if (row.shipCost != null) l.push('COSTO ENVÍO: ' + ars(row.shipCost));
    return l.join('\n');
  },
  comp(row) {
    if (!row.hasShip) return row.mainDoc || '';
    return ['COMPROBANTE PRINCIPAL: ' + (row.mainDoc || '—'), 'NDP DE ENVÍO: ' + (row.shipDoc || '—')].join('\n');
  },
  samePay(row) { return row.hasShip && !row.paySplit && String(row.payMain || '').trim().toUpperCase() === String(row.payShip || '').trim().toUpperCase() && !!String(row.payMain || '').trim(); },
  // Líneas de MODO DE PAGO (las usa la tabla, la impresión, el PDF y el Excel)
  pagoLines(row) { return this.markProv(row, this._pagoLines(row)); },
  _pagoLines(row) {
    if (row.payOverride != null && row.payOverride !== '') return row.payOverride.split('\n').map(v => ({ label: '', value: v, kind: 'plain' }));
    const p = Money.parts(row), k = Money.cob(row);
    const mM = String(row.payMain || '').trim() || 'REVISAR', mS = String(row.payShip || '').trim() || 'REVISAR';
    const L = (label, value, kind) => ({ label, value, kind: kind || 'main' });
    if (p.total == null) {
      const base = row.hasShip ? (this.samePay(row) ? [L('', mM)] : [L('', mM + ' / ' + mS)]) : [L('', mM)];
      return row.auto || row.montoManual ? base.concat([L('', 'SALDO NO ENCONTRADO / REVISAR')]) : base;
    }
    const tot = L('TOTAL:', ars(p.total), 'total');
    if (!row.hasShip) {
      if (k.m && !row.montoManual) return [L('', 'SIN COBRO'), tot];
      return [L('', mM + ' ' + ars(p.main))];
    }
    if (p.total === 0 && (k.m || k.s)) return [L('', 'SIN COBRO'), tot];
    if (p.main === 0 && k.m) return [L('', mS), L('ENVÍO:', ars(p.ship), 'ship'), L('MERCADERÍA:', 'COBRADA', 'muted'), tot];
    if (p.ship === 0 && k.s) return [L('', mM), L('MERCADERÍA:', ars(p.main)), L('ENVÍO:', 'COBRADO', 'muted'), tot];
    if (this.samePay(row)) return [L('', mM), L('MERCADERÍA:', ars(p.main)), L('ENVÍO:', ars(p.ship), 'ship'), tot];
    return [L(mM + ' — MERCADERÍA:', ars(p.main)), L(mS + ' — ENVÍO:', ars(p.ship), 'ship'), tot];
  },
  pago(row) { return this.pagoLines(row).map(l => (l.label ? l.label + ' ' : '') + l.value).join('\n'); },
  // Marca "A CONFIRMAR" en la línea del envío provisorio (pantalla, PDF, Excel e impresión)
  markProv(row, lines) {
    if (!(row.calc && row.calc.shipProv && row.calc.shipProv.status === 'PENDING_CONFIRMATION')) return lines;
    return lines.map(l => /ENVÍO:$/.test(l.label || '') && /^\$/.test(l.value) ? Object.assign({}, l, { value: l.value + ' · A CONFIRMAR' }) : l);
  }
};

/* ---------------- Money: montos finales por concepto ----------------
   Monto sugerido (sistema) ≠ monto final (lo que se cobra). Si el operador edita el MONTO,
   ese importe manda en toda la app hasta que use "↻ Usar monto sugerido". */
const Money = {
  cob(row) { return { m: row.cobradoMain === 'Sí', s: !!row.hasShip && row.cobradoShip === 'Sí' }; },
  // Sugeridos del sistema por concepto (sin considerar Cobrado)
  sug(row) {
    const c = row.calc;
    if (row.auto && c && c.suggested != null) return { ok: true, main: c.mainCollect, ship: row.hasShip ? (row.shipCostManual && row.shipCost != null ? row.shipCost : c.shipCollect) : 0 };
    return { ok: false, main: null, ship: row.hasShip ? (row.shipCost == null ? null : row.shipCost) : 0 };
  },
  parts(row, ignoreManual) {
    const s = this.sug(row), k = this.cob(row), warn = [];
    let main, ship;
    if (row.montoManual && !ignoreManual) {
      // MONTO editado por el operador = SOLO MERCADERÍA. El envío sigue su propio cálculo y su propio Cobrado.
      const M = row.montoMercaderiaManual;
      main = k.m ? 0 : (M == null ? null : M);
      ship = !row.hasShip ? 0 : (k.s ? 0 : (s.ship != null ? s.ship : (row.shipCost == null ? 0 : row.shipCost)));
    } else {
      main = k.m ? 0 : s.main;
      ship = !row.hasShip ? 0 : (k.s ? 0 : (s.ok ? s.ship : (row.auto ? null : s.ship)));
      if (!row.auto && !s.ok && !k.m) main = null;
    }
    const total = main == null || ship == null ? null : r2(main + ship);
    return { main, ship, total, warn };
  },
  suggestedTotal(row) { return this.parts(row, true).total; },
  suggestedMain(row) { return this.parts(row, true).main; },
  // El total de la fila (row.monto) siempre es: mercadería pendiente + envío pendiente
  apply(row) { row.monto = this.parts(row).total; },
  // Valor que se ve y se edita en el campo MONTO: la mercadería
  fieldValue(row) { return this.parts(row).main; }
};

/* ---------------- Agrupación por cliente ---------------- */
const Groups = {
  key(row) { const n = Normalizer.name(Normalizer.splitClient(row.cliente).name); return n ? 'c:' + n : 'id:' + row.id; },
  // Reordena la hoja: las entregas del mismo cliente quedan juntas (en el orden en que apareció cada cliente)
  regroup() {
    const order = [], map = new Map();
    RouteStore.rows.forEach(r => { const k = this.key(r); if (!map.has(k)) { map.set(k, []); order.push(k); } map.get(k).push(r); });
    RouteStore.rows = order.reduce((a, k) => a.concat(map.get(k)), []);
  },
  // Importes de una entrega separados por forma de pago (y tipo de comprobante)
  parts(row) {
    if (row.payOverride) return row.monto > 0 ? [{ method: row.payMain, amt: row.monto, tipo: Normalizer.compType(row.mainDoc) }] : [];
    const p = Money.parts(row), t = d => Normalizer.compType(d);
    if (p.total == null) return [];
    return [{ method: row.payMain, amt: p.main, tipo: t(row.mainDoc) }, { method: row.payShip, amt: p.ship, tipo: t(row.shipDoc) || 'NDP' }].filter(x => x.amt > 0);
  },
  // Grupos de clientes con más de una entrega
  list(rows) {
    const out = [], map = new Map();
    rows.forEach(r => { const k = this.key(r); if (!map.has(k)) { const g = { key: k, name: r.cliente, rows: [] }; map.set(k, g); out.push(g); } map.get(k).rows.push(r); });
    out.forEach(g => {
      const sale = g.rows.filter(r => r.sale);
      const by = new Map();
      sale.forEach(r => this.parts(r).forEach(p => {
        const m = String(p.method || 'SIN FORMA DE PAGO').trim().toUpperCase();
        if (!by.has(m)) by.set(m, { method: m, amt: 0, tipos: new Set() });
        const e = by.get(m); e.amt = r2(e.amt + p.amt); if (p.tipo) e.tipos.add(p.tipo);
      }));
      g.sale = sale;
      g.total = r2(sale.reduce((s, r) => s + (r.monto || 0), 0));
      g.pending = sale.filter(r => r.monto == null).length;
      g.methods = Array.from(by.values()).map(e => ({ method: e.method, amt: e.amt, label: e.method + (e.tipos.size ? ' (' + Array.from(e.tipos).map(t => t === 'FAC' ? 'facturas' : t === 'NDP' ? 'notas de pedido' : t).join(' + ') + ')' : '') }));
    });
    return out;
  },
  text(g) {
    return g.methods.map(e => e.label + ': ' + ars(e.amt)).join(' · ') + (g.pending ? ' · ' + g.pending + ' sin monto' : '');
  }
};

